window.DOSIK=window.DOSIK||{};DOSIK["sm_fin"]={"1":[{"t":"table","title":"파레토 효율","head":["구분","내용"],"rows":[["교환의 효율","두 소비자의 한계대체율(MRS)이 같을 때 이루어진다"],["생산의 효율","두 산업의 한계기술대체율(MRTS)이 같을 때 이루어진다"],["산출물 구성","산출물 구성까지 효율적이려면 MRS = MRT여야 한다"],["생산가능곡선 위의 점","생산 효율만 보장하므로 MRS가 MRT와 다르면 생산 구성을 바꿔 모두를 낫게 할 수 있다"],["파레토 개선","누구의 효용도 줄이지 않고 한 사람 이상의 효용을 늘리는 변화"],["개선 여지가 남은 배분","비효율적이다"],["효용가능경계 위의 배분","모두 파레토 효율적이며 그런 점은 무수히 많다 · 경계 위에서는 효율과 공평을 함께 높일 수 없다"]]},{"t":"vs","title":"후생경제학의 기본정리","cols":[{"name":"제1정리","items":["외부성이 없고 시장이 완비된 완전경쟁의 일반균형이 파레토 효율적이라는 것으로 보이지 않는 손을 뜻한다"]},{"name":"제2정리","items":["선호와 생산이 볼록하면 초기부존을 재분배해 어떤 파레토 효율적 배분도 경쟁균형으로 이룰 수 있다는 것이다","분배 문제를 효율과 떼어 다룰 수 있다는 뜻일 뿐 효율이 공평을 보장한다는 뜻은 아니다"]}]},{"t":"table","title":"사회후생함수","head":["구분","내용"],"rows":[["유형","효용을 측정·비교할 수 있다고 보고 그 사회의 가치판단에 따라 모양이 정해진다"],["공리주의","W = U_A + U_B는 모두에게 같은 가중치를 주고 각자 소득의 한계효용이 같을 때 후생이 가장 크다"],["평등주의","효용이 낮은 사람에게 큰 가중치를 주며 이 성향이 극단으로 가면 롤즈의 W = min(U_A, U_B)가 되어 사회무차별곡선이 L자다"],["극대화 계산(공리주의)","X재 1,000단위를 U_A = 3√X_A, U_B = √X_B인 두 사람에게 나눌 때 3/(2√X_A) = 1/(2√X_B)에서 X_A = 900, X_B = 100이고 W = 100이다"],["극대화 계산(롤즈 함수)","3√X_A = √X_B에서 X_A = 100, X_B = 900이고 W = 30이다 · 같은 재화가 순수공공재라면 둘 다 1,000을 소비하므로 롤즈 후생은 낮은 쪽인 B의 효용 √1,000으로 정해진다"]]},{"t":"table","title":"시장실패와 자연독점","head":["구분","내용"],"rows":[["시장실패의 원인","불완전경쟁·공공재·외부성·정보의 비대칭·불완비 시장(보험시장 등)이 시장실패를 낳는다"],["시장실패와 정부개입","시장실패는 정부개입의 필요조건일 뿐 충분조건이 아니다 · 정부가 정보 부족이나 민간 반응을 다 통제하지 못해 정부실패가 생길 수 있다"],["역선택","거래 전에 숨은 특성 때문에 생기며 졸업장·자격증 같은 신호발송, 품질보증, 책임보험·국민연금 강제가입으로 줄인다"],["도덕적 해이","거래 뒤 숨은 행동 때문에 생기며 CCTV 감시·공동보험·성과급처럼 행동을 살피거나 유인을 맞춰 줄인다 · 애로는 완벽한 조건부거래시장이 있으면 불확실성이 있어도 시장실패가 없음을 보였다"],["자연독점","평균비용이 계속 줄어드는 구간에서는 한계비용이 평균비용보다 작아 한 기업이 생산하는 편이 싸다"],["한계비용가격설정(P = MC)","효율적 생산량을 내지만 P < AC라 손실이 나서 일반 세원으로 메워야 한다"],["평균비용가격설정(P = AC)","손실이 없으나 과소생산이 남고 비용절감 유인을 주지 못한다"],["유기체적 국가관","사회를 하나의 유기체로 보고 개인은 그 한 부분이며 정부는 심장부라고 본다 · 전체의 이익에 봉사하는 것이 개인의 미덕이라는 전체주의적 사고다"],["기계적 국가관","반대로 정부를 개인의 목적을 이루기 위한 도구로 본다"]]}],"2":[{"t":"table","title":"공공재의 성질과 분류","head":["구분","내용"],"rows":[["비경합성","한 사람이 더 소비해도 남의 소비가 줄지 않는 성질로 소비자 추가의 한계비용이 0이다"],["비배제성","대가를 내지 않은 사람도 소비에서 막을 수 없는 성질이다"],["순공공재","순수공공재는 둘을 모두 갖추며 현실의 공공재는 대부분 일부만 갖춘 비순수공공재다"],["클럽재","배제가 가능하고 이용자가 늘면 혼잡이 생기는 재화로 시장에서도 효율적으로 공급될 수 있다"],["공유자원","배제가 어렵지만 경합적이라 남용된다"],["가치재","사적재이지만 정부가 소비를 장려하려고 공급하거나 지원하는 재화이고 상수도·우편·철도도 사적재 성격이 강하다"]]},{"t":"tree","title":"사무엘슨 조건","root":"**사무엘슨 조건**","branches":[["효율적 공급","각 개인 한계대체율의 합이 한계변환율과 같은 ΣMRS = MRT, 곧 한계편익의 합이 한계비용과 같을 때다"],["시장수요곡선","개별수요곡선을 수직으로 더해 구한다"],["소비와 가격","모두 같은 양을 소비하지만 각자 다른 가격을 치르고 그 가격의 합이 한계비용과 같다"],["최적 공급량 계산","MU_A = 4 − X, MU_B = 8 − 2X, MC = 2X이면 (4 − X) + (8 − 2X) = 2X에서 X = 2.4다"],["같은 수요가 여럿","1인 역수요에 인원수를 곱한 뒤 그룹끼리 더한다 · 해안 6명이 P = 200 − 2Q, 내륙 4명이 P = 150 − 3Q이고 MC = 840이면 1,800 − 24Q = 840에서 Q = 40이고 1인 부담은 120과 30이다"]]},{"t":"vs","title":"무임승차와 린달 모형","cols":[{"name":"무임승차","items":["비배제성 때문에 각자는 선호를 숨기고 남이 낸 비용으로 소비하려 한다","두 사람이 공공재 비용 분담에 찬반을 고르는 게임에서 반대가 우월전략이면 서로 반대하는 것이 유일한 내쉬균형이 된다","그래서 시장에 맡기면 공공재가 과소공급된다"]},{"name":"린달 모형","items":["각자가 공공재 비용의 부담비율을 제시하며 자발적으로 합의해 공급량을 정한다","균형에서 각자의 부담비율은 자기 한계편익에 맞춰지고 부담비율의 합은 1이어서 사무엘슨 조건이 충족된다","사람들이 선호를 숨기면 무너지므로 소수일 때만 현실성이 있다"]}]},{"t":"table","title":"린달 계산과 요금","head":["구분","내용"],"rows":[["린달 가격 계산","Z_A = 100 − 20P, Z_B = 100 − 10P이고 MC = 3이면 역수요는 P_A = 5 − Z/20, P_B = 10 − Z/10이다 · 합 15 − 0.15Z = 3에서 Z = 80이고 P_B = 2이므로 B의 부담비율은 2/3다 · 수요가 P_1 = 50 − Q, P_2 = 40 − (2/3)Q이고 단위비용 60이면 Q = 18에서 부담은 32와 28이다"],["클라크세","각자가 낼 세금은 자기 표출 선호가 아니라 다른 사람들이 표출한 선호로 정해진다 · 진정한 선호를 밝히는 것이 우월전략이 되어 무임승차 없이 효율적 공급이 가능하다 · 다만 거둔 세금과 비용이 맞지 않아 정부의 균형예산은 늘 충족되지는 않는다"],["이부가격제","기본요금으로 고정비 결손을 메우고 사용료를 한계비용에 맞춰 결손을 줄이면서 효율적 생산량에 이를 수 있다"],["시설이 남는 비수기와 초과수요","시설이 남는 비수기에는 한계비용만 받고 용량이 차서 초과수요가 있으면 한계비용에 경제적 지대를 더해 받는 것이 효율적이다"],["램지가격","수요의 가격탄력성이 작을수록 가격을 한계비용보다 높게 매기므로 필수품에서 분배 문제가 생긴다"]]}],"3":[{"t":"table","title":"외부성의 종류와 생산량","head":["구분","내용"],"rows":[["외부성","한 사람의 행동이 대가 없이 제3자에게 이득이나 손해를 주는 현상으로 생산과 소비 모두에서 생긴다"],["해로운 외부성","사회적 최적보다 과다 생산된다"],["이로운 외부성","연구개발, 양봉과 과수원이 있으면 과소 생산된다"],["효율적 배분","사회적 한계편익과 사회적 한계비용이 같을 때다"],["기술적(실질적) 외부성","시장 밖에서 직접 효용이나 생산에 영향을 주어 비효율을 낳는다"],["금전적 외부성","대규모 공사로 건축자재 값이 올라 다른 업자가 손해를 보는 것처럼 상대가격 변동을 거쳐 전달된다 · 분배만 바꿀 뿐 자원배분의 효율성에는 영향이 없다"]]},{"t":"tree","title":"피구세와 보조금","root":"**외부성의 교정**","branches":[["피구세","외부성을 일으키는 쪽에 최적 생산량에서의 한계피해(MD)만큼 단위당 세금을 매겨 외부비용을 사적 비용에 반영하며 오염세를 내는 기업은 배출을 줄일수록 세금이 줄어 감축기술 개발 유인을 갖는다"],["피구세 계산","PMB = 600 − 4Q, PMC = 6Q, MD = 2Q이면 SMC = 8Q이고 600 − 4Q = 8Q에서 Q = 50, 세액은 2 × 50 = 100이다"],["A와 B의 비용","A의 비용이 X² + 4X, B의 비용이 Y² + 3Y + X라면 A의 생산이 B에 비용을 주므로 환경세는 A에 부과하고 합병·배출권 시장 개설·협상·수량규제도 효율적 배분 수단이 된다"],["이로운 외부성과 보조금","SMB = PMB + EMB가 한계비용과 같은 곳이 최적이다 · PMB = 150 − Q, EMB = 30 − Q/4, PMC = Q이면 SMB = 180 − 1.25Q에서 최적 Q = 80이고 시장이 80을 고르게 하는 단위당 보조금은 10이다"],["보조금의 효과","단기에는 세금과 같은 효과를 내지만 장기에는 진입을 불러 산업 생산량을 덜 줄인다"]]},{"t":"vs","title":"코즈 정리","cols":[{"name":"코즈 정리의 내용","items":["재산권이 명확하고 거래비용이 작으면 권리를 가해자와 피해자 누구에게 주든 자발적 협상으로 같은 효율적 수준에 이른다","정부의 직접 개입 없는 사적 해결 방안이며 형평성은 다루지 않아 분배 문제는 남는다","소득효과가 없어야 하고 협상 이득이 협상 비용보다 커야 한다"]},{"name":"코즈 정리의 한계와 계산","items":["당사자가 많거나 피해 규모 정보가 비대칭이면 거래비용이 커져 현실 적용이 어렵고 정부 개입이 정당화된다","공장 MB = 120 − Q, 피해 MD = Q/2이면 효율적 생산량은 Q = 80이다","권리가 공장에 있으면 공장은 Q = 120까지 생산하려 하므로 피해자가 줄 최소 금액은 Q 80~120 구간 MB 면적 800이다"]}]},{"t":"table","title":"배출권거래제와 공유지","head":["구분","내용"],"rows":[["배출권거래제","정부가 배출 총량을 정해 나눠 주면 한계저감비용이 낮은 기업은 배출권을 팔고 높은 기업은 산다 · 균형에서는 기업마다 한계저감비용이 같아지고 처음 할당과 상관없이 총 저감비용이 최소가 된다 · 총량이 정해져 있어 감축량이 확실하고 불확실한 것은 배출권 가격이다"],["배출권 가격 계산","A·B가 각각 500을 배출하고 저감비용이 40 + q_A²/2, 30 + q_B²이면 한계저감비용은 q_A와 2q_B다 · 총배출 30%인 300을 줄이면 q_A = 200, q_B = 100이고 배출권 가격은 200이다 · A에 400, B에 300을 할당했다면 A는 100을 팔고 B는 100을 사므로 거래량은 100이다"],["공유지의 비극","소유권이 분명하지 않은 자원은 각자 아껴 쓸 유인이 없어 남용되고 빨리 고갈된다 · 한 사람의 사용이 다른 사용자에게 외부성을 주기 때문이며 연근해 어족 자원 고갈이 대표적이다"]]}],"4":[{"t":"table","title":"중위투표자 정리와 투표의 역설","head":["구분","내용"],"rows":[["중위투표자 정리","모든 투표자의 선호가 단봉형이면 단순다수결의 결과는 선호가 한가운데 있는 중위투표자가 원하는 안이 된다"],["예산안 예","10억·20억·30억 예산안이면 중위인 20억이 꽁도세 승자다"],["의미와 한계","양당의 공약이 중위투표자 쪽으로 비슷해지는 현상을 설명하지만 그 균형이 파레토 효율을 보장하지는 않는다"],["투표의 역설","A: x > y > z, B: y > z > x, C: z > x > y처럼 선호가 엇갈리면 다수결 결과가 x > y > z > x로 순환해 이행성이 깨진다"],["역설의 결과","이때는 대진 순서에 따라 승자가 달라지고 의사진행 조작이 가능하다 · 다봉형 선호가 섞이면 생기며 중위투표자 정리도 성립하지 않는다"]]},{"t":"table","title":"애로의 정리와 꽁도세 승자","head":["구분","내용"],"rows":[["애로의 불가능성 정리","완비성·이행성, 파레토 원칙, 무관한 대안의 독립성, 비독재성을 모두 만족하는 사회적 선호체계는 없다 · 개인 선호에서 합리적이고 민주적인 집단 선택 규칙을 만들 수 없다는 뜻이다"],["센","선택 대상이 제한된 경우 이런 서열을 만들 수 있다고 보았다"],["꽁도세 승자","다른 모든 대안과 1대1 다수결로 겨뤄 모두 이기는 대안이다 · 투표의 역설이 있으면 존재하지 않고 강선호라면 있더라도 하나뿐이다"],["과반수 득표자","반드시 꽁도세 승자이지만 과반이 안 되는 최다득표자는 아닐 수 있다"]]},{"t":"vs","title":"보다투표와 최적다수결제","cols":[{"name":"보다투표와 점수투표","items":["보다투표는 순위에 점수를 매겨 합한다","대안 4개에 1순위 3점부터 4순위 0점을 주고 A형 4명·B형 3명·C형 2명의 순위를 합산하면 b가 19점으로 뽑힌다","전략적 행동이 없다면 선호의 강도를 가장 잘 반영하는 방식은 점수투표제다"]},{"name":"최적다수결제","items":["가결에 필요한 찬성 비율이 높을수록 의사결정비용은 커지고 반대자가 떠안는 외부비용은 작아진다","최적 가결률은 두 비용의 합이 가장 작은 곳이다","총비용이 4n² − 2n + 15라면 8n − 2 = 0에서 n = 1/4이고 전원합의제로 공공재를 배분하는 예로는 린달 모형이 있다"]}]},{"t":"table","title":"다수결과 관료 모형","head":["구분","내용"],"rows":[["다수결과 공공재 공급","공공재가 정상재면 고소득자의 수요가 더 크고 중위투표자의 소득이 오르면 공공재 수요량도 늘어난다 · 비례적 소득세로 비용을 나누면 다수결 결과가 최적보다 과대 공급될 수 있다"],["과다공급과 과소공급","소수에게 비용을 떠넘기는 다수결과 투표거래(로그롤링)는 과다공급을 낳고 다운즈의 합리적 무지와 갤브레이스의 의존효과는 과소공급을 설명한다"],["니스카넨 관료 모형","관료는 공공서비스의 독점 공급자로서 예산 극대화를 추구해 총편익과 총비용이 같아지는 곳까지 생산한다 · 수요 P = 16 − Q/2, MC = 12이면 효율적 규모는 8이지만 관료는 16Q − Q²/4 = 12Q에서 Q = 16을 고른다 · 그 생산수준에서 사회적 잉여는 0이 된다"],["미그-빌레인저 모형","관료는 재량예산(실제 비용을 넘는 여유 예산)을 크게 하려 한다 · 그래서 생산량은 효율적 수준보다 많지만 니스카넨 모형보다는 적다 · 니스카넨은 대응책으로 민간이 생산하고 정부는 비용만 대는 방식을 제안했다"]]}],"5":[{"t":"table","title":"비용편익분석의 평가 기준","head":["구분","내용"],"rows":[["평가 기준","순현재가치(NPV)가 0보다 크거나 편익·비용비율(B/C)이 1보다 크거나 내부수익률(IRR)이 할인율보다 크면 사업을 채택한다"],["IRR","NPV를 0으로 만드는 할인율이다 · 여러 사업의 우선순위는 NPV 크기로 정하며 IRR과 NPV의 결론이 늘 같지는 않다"],["NPV와 IRR의 충돌 계산","비용 1,000을 들여 A는 2년 뒤 1,210, B는 1년 뒤 1,150을 얻는다면 IRR은 A 10%, B 15%다 · 할인율 7%에서 NPV는 A 56.9, B 74.8로 B가 낫다 · 할인율이 약 5.2%보다 낮으면 A의 NPV가 더 커져 순위가 바뀐다"],["할인율 선택","사업 자금의 기간당 기회비용에 맞춘다 · 할인율이 높을수록 먼 미래 편익이 크게 깎여 편익이 초기에 몰린 단기 사업이 유리하다 · 시장이자율이 사회적 할인율보다 높은데 시장이자율을 쓰면 공공사업의 경제성이 낮게 평가된다"]]},{"t":"table","title":"칼도-힉스 기준과 잠재가격","head":["구분","내용"],"rows":[["칼도-힉스 기준","사업으로 이득을 보는 사람이 손해 보는 사람을 보상하고도 남으면 채택한다는 잠재적 파레토 개선 기준이다 · 실제로 보상할 필요는 없다"],["적용 범위","비용편익분석은 공공부문뿐 아니라 민간 투자계획의 타당성 판정에도 쓰인다"],["잠재가격","시장이 불완전하거나 왜곡되면 시장가격 대신 사회적 기회비용인 잠재가격을 쓴다"],["독점 상품","독점 상품을 사서 그만큼 생산이 늘면 한계비용으로, 생산이 그대로면 시장가격으로 평가한다"],["물품세가 붙은 투입물","생산이 그대로면 소비자가격으로, 생산이 늘면 생산자가격으로 평가한다"]]},{"t":"vs","title":"편익의 구분","cols":[{"name":"실질적 편익","items":["최종소비자가 얻어 사회후생을 늘린다","사업으로 시장가격이 내리면 늘어난 소비자잉여를 편익에 넣는다","시장에서 파악되지 않는 무형의 편익·비용과 외부적 편익도 함께 고려한다"]},{"name":"금전적 편익","items":["상대가격 변화로 소득이 옮겨 갈 뿐이라 편익에 넣지 않는다"]}]},{"t":"table","title":"비시장재 가치와 불확실성","head":["구분","내용"],"rows":[["회피행위접근법","정수기·방독면처럼 오염 위험을 피하려고 쓰는 돈으로 편익을 잰다"],["조건부가치측정법","설문으로 지불의사를 묻는다"],["헤도닉가격법과 여행비용법","헤도닉가격법은 주택가격 같은 시장자료, 여행비용법은 방문 비용으로 환경가치를 추정한다 · 지금 임금률로 더 일하고 싶어도 못 하는 사람의 시간가치는 임금률보다 낮게 본다"],["확실성등가","기대값에서 위험프리미엄을 뺀 값이라 위험회피 성향이 클수록 작아진다 · 순편익이 음수(비용)라면 위험할인율만큼 비용을 더 크게 잡는다 · 50년 뒤 순편익 −100억 원, 위험할인율 20%, 이자율 10%이면 현재가치는 −100억 원 × 1.2 ÷ 1.1⁵⁰이다"],["비용효과분석","무형 편익을 돈으로 재기 힘들면 같은 목표를 가장 싸게 이루는 대안을 고르는 비용효과분석을 쓴다 · 할인율 10%에서 지금 −3,000, 1년 뒤 1,100, 2년 뒤 2,420이면 NPV = −3,000 + 1,000 + 2,000 = 0이다"]]}],"6":[{"t":"vs","title":"편익원칙과 능력원칙","cols":[{"name":"편익원칙","items":["공공서비스에서 얻는 편익만큼 내라는 원칙으로 빅셀의 자발적 교환이론에 기초한다","통행료·사용료·수수료, 주행거리에 비례한 자동차세가 예다","근로의욕을 해치지 않지만 재분배 재원을 마련하기 어렵고 편익에 비례해 걷어도 무임승차가 생길 수 있다"]},{"name":"능력원칙","items":["부담능력이 다르면 세금도 달라야 한다는 원칙으로 밀의 동등희생 원칙에 근거한다"]}]},{"t":"table","title":"공평과 조세 원칙","head":["구분","내용"],"rows":[["수평적 공평","같은 능력에 같은 세금이고 포괄적 소득세가 이를 높인다"],["수직적 공평","능력이 클수록 더 내는 것이고 소득세 누진성 강화가 이를 높이지만 평균소득이 같아도 소득 변동이 큰 사업자는 누진세로 더 내게 되어 수평적 공평이 깨질 수 있다"],["스미스의 조세 원칙","공평·확실(납부 시기·방법·금액을 알 수 있게)·편의·최소징세비이며 수입 극대화는 원칙이 아니다"]]},{"t":"table","title":"직접세·간접세·목적세","head":["구분","내용"],"rows":[["직접세","법인세 등은 납세의무자와 담세자가 같고 누진과세가 가능해 소득분배 개선에 유리하다"],["간접세","부가가치세 등은 가격에 숨어 조세저항과 징세비용이 작지만 역진적이다"],["목적세","국세로 교육세·교통·에너지·환경세·농어촌특별세, 지방세로 지방교육세·지역자원시설세가 있고 재원을 안정적으로 확보하지만 재정 운영을 경직시킨다"]]},{"t":"table","title":"귀착과 조세 계산","head":["구분","내용"],"rows":[["법적 귀착과 경제적 귀착","법적 귀착은 법이 정한 납세자, 경제적 귀착은 실제 부담자이며 둘은 다를 수 있다"],["전방전가","법인세 부담이 상품가격 인상으로 소비자에게 넘어가면 전방전가다"],["절대·차별·균형예산귀착","절대귀착은 다른 조세·지출을 그대로 두고 한 조세만 보고 차별귀착은 같은 세수의 다른 조세로 바꿀 때를 보며 균형예산귀착은 그 세수로 한 지출의 분배효과까지 본다"],["물품세와 탄력성","수요자와 공급자 중 누구에게 부과하든 결과가 같고 상대적으로 비탄력적인 쪽이 더 많이 부담한다 · 소비자 부담 : 생산자 부담 = 공급탄력성 : 수요탄력성이고 수요가 완전비탄력적이면 소비자가 전부 낸다 · 탄력성이 클수록 거래량이 많이 줄어 후생손실이 커지고 세율을 올려도 세수가 늘지 않을 수 있다"],["경쟁시장 귀착 계산","Q = 120 − 2P, Q = P에서 균형가격은 40이다 · 소비자에게 단위당 12를 과세하면 생산자 수취가격이 32가 되어 생산자가 8, 소비자가 4를 부담한다 · Q_d = 50 − 2P, Q_s = 3P − 20에 생산자 과세 10이면 P가 14에서 20으로 오르고 Q = 10이라 세수 100, 후생손실은 ½ × 10 × 12 = 60이다"],["생산요소 과세","노동수요가 완전탄력적이거나 노동공급이 비탄력적이면 근로소득세는 근로자가 대부분 진다 · 완전 개방경제에서 자본에 과세하면 자본은 빠져나갈 수 있어 이동하지 못하는 자본 사용자 쪽이 부담한다"],["토지 과세와 자본화","공급이 고정된 토지에 과세하면 미래 세금의 현재가치만큼 땅값이 내려 과세 시점의 소유자가 모두 부담하고 이 자본화의 크기는 할인율에 반비례한다"],["독점과 조세","독점에는 공급곡선이 없어 공급탄력성으로 귀착을 설명할 수 없고 세금 일부만 소비자에게 넘어간다 · Q = 300 − 3P, MC = Q + 10인 독점에 단위당 20을 과세하면 생산량이 54에서 42로 줄고 소비자 4, 독점기업 16을 부담한다 · 생산량이 같다면 종가세의 세수가 종량세보다 많고 이윤세는 이윤극대화 생산량을 바꾸지 않는다"],["알링햄-샌드모 탈세모형","탈세를 기대효용 극대화 문제로 보고 납세자의 절대위험기피도가 체감한다고 가정한다 · 세율이 오르면 소득효과는 탈세를 줄이고 대체효과는 늘려서 방향이 불분명하지만 감사확률과 벌금률을 높이면 탈루소득이 준다 · 세율은 적정하게 두고 행정비용이 덜 드는 벌금률 인상으로 탈세를 막는 쪽이 낫다고 본다"]]}],"7":[{"t":"table","title":"초과부담","head":["구분","내용"],"rows":[["초과부담","과세로 상대가격이 바뀌어 생기는 선택의 왜곡으로 소비자·생산자 후생 감소분에서 조세수입을 뺀 값이다"],["대체효과","소득효과가 아니라 대체효과 때문에 생기므로 보상수요곡선으로 재야 한다 · 소득효과와 대체효과가 상쇄되어 수요량이 그대로여도 초과부담은 생긴다"],["정액세","행동과 관계없이 걷으므로 초과부담이 없고 현금보조는 음(−)의 정액세라 초과부담이 없다"],["중립적 과세","소득세·일반소비세나 모든 재화에 같은 세율을 매기면 재화 사이 상대가격이 그대로라 재화 선택에 중립적이고 특정 재화에만 물품세를 매기면 선택이 왜곡된다"],["2기간 생애주기모형","이자소득세 없이 근로소득세만 매기면 현재와 미래 소비의 상대가격이 그대로라 대체효과에 의한 초과부담이 없다"]]},{"t":"table","title":"초과부담 공식과 계산","head":["구분","내용"],"rows":[["물품세 초과부담 공식","½ · t² · PQ · ε_dε_s/(ε_d + ε_s)로 세율의 제곱과 탄력성에 비례한다 · 공급곡선이 수평이면 ½ · ε · t² · PQ(ε는 보상수요의 가격탄력성)가 된다"],["세율과 탄력성","세율이 2배면 초과부담은 4배로 커지고 세수는 늘지 않을 수도 있으며 대체재가 적어 수요가 비탄력적인 재화일수록 초과부담이 작다"],["초과부담 계산 1","P = 1,000, Q = 1,000, 수요·공급탄력성이 모두 0.1인 상품에 10% 종가세를 매기면 ½ × 0.01 × 1,000,000 × (0.01/0.2) = 250이다"],["초과부담 계산 2","한계비용 50이 일정하고 보상수요가 P = 100 − Q일 때 단위당 20을 과세하면 Q가 50에서 30으로 줄어 세수 600, 사중손실 200이고 비효율성계수는 1/3이다 · 공급이 Q = 50으로 고정되어 있으면 거래량이 변하지 않아 사중손실은 0이다"]]},{"t":"table","title":"완전보완재와 램지 규칙","head":["구분","내용"],"rows":[["완전보완재","두 재화가 완전보완재면 한 재화에 과세해도 보상수요량이 변하지 않아 초과부담이 0이다 · 세수가 같다면 한 재화에 몰아 걷기보다 두 재화에 나눠 걷을 때 초과부담이 작다"],["차선의 이론","대체재인 X재에 이미 세금이 있으면 Y재에 새로 과세해 경제 전체의 초과부담이 오히려 줄 수 있다"],["램지 규칙","세수 1원을 더 걷을 때의 한계초과부담이 모든 재화에서 같도록 세율을 정하면 보상수요량의 감소율이 모든 재화에서 같아진다"],["역탄력성 원칙","재화끼리 수요가 독립적이면 세율은 수요의 가격탄력성에 반비례하는 역탄력성 원칙이 되어 필수재에 높은 세율이 붙는다 · 효율성만 본 원칙이라 필수재에 낮은 세율을 매기는 것은 램지 규칙에는 어긋나도 공평 면에서는 바람직할 수 있다"]]},{"t":"table","title":"램지 가격과 최적과세","head":["구분","내용"],"rows":[["램지 가격","공공요금에도 (P − MC)/P = k/ε가 적용된다 · MC_X = 20, P_X = 25, MC_Y = 30, P_Y = 50이고 Y의 탄력성이 1이면 0.4 = k에서 X의 탄력성은 0.2 = 0.4/ε로 2다"],["오이(Oi)의 최적이부요금","고정 수수료에 대한 탄력성이 클수록 고정 수수료를 낮추고 사용 요금을 높이며 단일요금보다 효율적이다"],["구간별 세율 조정","세수가 일정할 때 효용을 최대로 하려면 과세구간마다 한계세수당 한계효용(MU/MR)이 같아야 한다 · 이 비율이 낮은 구간은 세율을 올리고 높은 구간은 세율을 내린다 · 가격차별 독점도 같은 논리로 시장마다 MR = P(1 − 1/ε)를 같게 하므로 탄력성 2인 가정용이 1,200원이면 탄력성 3인 산업용은 900원이다"],["멀리스의 비선형 최적소득세","효율과 공평을 함께 보며 한계세율은 0과 1 사이이고 최고 소득 구간의 한계세율은 0이다 · 이 체계에서 임금률이 낮은 사람이 높은 사람보다 큰 효용을 누리지는 않는다"],["스턴의 선형소득세 분석","불평등 혐오도가 클수록·세수 목표가 클수록 최적 한계세율이 높고 노동공급이 탄력적일수록 낮다"]]}],"8":[{"t":"table","title":"세수함수와 세율 계산","head":["구분","내용"],"rows":[["세수함수","T = −300 + 0.3Y이면 한계세율은 0.3으로 일정하고 평균세율 0.3 − 300/Y는 소득과 함께 오르지만 늘 0.3보다 낮으며 소득공제 1,000을 둔 선형누진세다"],["누진세와 비례세","평균세율이 소득과 함께 오르면 누진세이고 세수탄력성(한계세율/평균세율)이 1보다 크다 · 한계세율과 평균세율이 같으면 비례세다"],["한계세율과 실효세율 계산","과세소득이 1,200만원까지 0%, 3,000만원까지 9%, 5,000만원까지 18%인 구조에서 과세소득 4,500만원이면 세액은 162만 + 270만 = 432만원이다 · 한계세율은 마지막 구간의 18%이고 실효세율은 총소득 5,500만원으로 나눈 약 7.85%다"]]},{"t":"vs","title":"소득공제와 세액공제","cols":[{"name":"소득공제","items":["감세액은 공제액 × 한계세율이라 누진세에서는 소득이 클수록 혜택이 크다"]},{"name":"세액공제","items":["한계세율과 관계없이 같은 금액을 깎아 주므로 감면 총액이 같다면 소득공제를 세액공제로 바꿀 때 수직적 공평이 나아진다","특정 재화 구입비를 공제하면 그 재화의 상대가격이 낮아지며 우리나라 교육비는 세액공제 대상이다"]}]},{"t":"table","title":"소득세와 노동공급·저축","head":["구분","내용"],"rows":[["비례소득세","대체효과로 노동공급을 줄이고 여가가 정상재면 소득효과로 늘려 총효과가 불분명하다"],["후방굴절과 열등재","소득효과가 대체효과보다 크면 노동공급곡선이 후방굴절하고 여가가 열등재면 두 효과 모두 노동공급을 줄인다"],["정액세","대체효과 없이 소득효과만 있어 여가가 정상재면 노동공급이 늘고 열등재면 준다"],["이자소득세","세후 이자율이 내리면 현재소비의 상대가격이 내린다 · 현재소비는 대체효과로 늘고 소득효과로 줄어 방향이 불분명하며 미래소비는 두 효과 모두 줄이고 저축의 증감도 알 수 없다"],["세후 실질수익률","명목이자율 5%, 세율 20%, 물가상승률 3%이면 세후 실질수익률은 5 × 0.8 − 3 = 1%다"]]},{"t":"table","title":"위험부담·과세단위·법인세","head":["구분","내용"],"rows":[["위험부담과 손실상계","완전손실상계가 있으면 정부가 수익과 손실을 함께 나눠 지므로 위험자산의 비중이 커진다(도마-머스그레이브) · 손실상계가 없으면 대체효과는 위험자산을 줄이고 소득효과가 대체효과보다 클 때만 비중이 늘어난다 · 위험부담의 소득탄력성이 양(+)이면 손실상계가 없을 때 두 효과 모두 위험자산 투자를 줄인다"],["부부 합산과세","소득이 같은 가족에 같은 세금을 매겨 수평적 공평을 지키지만 결혼으로 세부담이 달라져 결혼중립성이 깨지고 개인단위 과세는 그 반대다 · 우리나라 개인소득세는 개인단위로 과세한다"],["인플레이션","명목소득과 물가가 함께 오르면 비례세의 실질세액은 그대로지만 누진세는 높은 구간으로 밀려 실질 부담이 커진다"],["자본의 사용자비용","조겐슨의 신고전파 투자이론에서 투자는 자본의 사용자비용(자본재 보유의 기회비용)이 낮을수록 늘어난다 · 가속상각·투자세액공제·법인세율 인하는 사용자비용을 낮추며 즉시상각하고 이자공제를 막거나 귀속이자까지 공제하고 경제적 감가상각을 따르면 법인세는 투자에 중립적이다 · 한계실효세율은 (세전 수익률 − 세후 수익률)/세전 수익률로 음수면 조세가 투자를 촉진하고 사용자비용탄력성이 작을수록 조세정책 효과도 작다"],["법인세 구조와 통합","자기자본의 귀속이자는 비용으로 인정하지 않고 차입 이자만 공제하므로 부채비중을 높일수록 법인세가 줄고 자금조달 방식이 왜곡된다 · 모딜리아니-밀러 제1명제는 법인세·파산비용·정보비대칭이 없으면 자본구조가 기업가치와 무관하다는 것이다 · 법인세와 소득세의 완전통합은 조합방식·자본이득방식, 부분통합은 배당세액공제·차등세율제도이며 대부분의 나라는 부분통합을 쓴다"]]}],"9":[{"t":"table","title":"물품세와 부가가치세","head":["구분","내용"],"rows":[["물품세의 가격효과","X재에 물품세를 매기면 X의 상대가격이 올라 대체효과로 X는 줄고 Y는 는다 · 실질소득이 줄어 소득효과로 정상재 소비는 줄고 열등재 소비는 는다 · X가 열등재라면 X재의 대체효과와 소득효과가 반대 방향으로 작용한다"],["부가가치세의 구조","생산·유통 각 단계에서 새로 붙은 부가가치에만 과세하는 일반소비세로 1954년 프랑스에서 처음 등장했다"],["매입세액공제방식","우리나라는 매출세액에서 매입세액을 빼는 매입세액공제방식을 써서 거래 상대방끼리 세금계산서로 서로 확인되어 탈세를 막는다 · 미국은 연방 부가가치세가 없고 주 정부가 소매판매세를 걷는다"]]},{"t":"table","title":"부가가치세의 유형과 면세","head":["구분","내용"],"rows":[["총소득형","자본재 구입비를 빼지 않는다"],["소득형(순소득형)","중간투입물 외에 감가상각비를 추가로 빼서 과세한다"],["소비형","자본재 구입비를 산 해에 전부 빼므로 과세 대상이 소비와 같아지고 투자를 촉진한다 · 우리나라는 소비형을 채택하고 있다"],["영세율","매출에 0% 세율을 적용하고 앞 단계에서 낸 매입세액을 환급해 주므로 부가가치세 부담이 완전히 사라지는 완전면세이며 수출품에 쓴다"],["면세","그 단계의 매출에만 세금을 면제하고 중간단계의 매입세액은 공제·환급하지 않는 부분면세다 · 기초생활필수품이 면세 대상이다"]]},{"t":"tree","title":"부가가치세의 장단점","root":"**부가가치세**","branches":[["수직적 통합","부가가치에만 과세하므로 기업을 수직적으로 합쳐도 세부담이 같아 수직적 통합을 부추기지 않는다"],["조세저항","가격에 포함되어 소득세보다 조세저항이 작다"],["역진성","단일세율이면 소득 대비 부담이 저소득층에 무거운 역진적 세금이다"]]},{"t":"table","title":"재산세와 부동산 조세","head":["구분","내용"],"rows":[["재산세(자산과세)","납세자가 소유자이지만 물건을 기준으로 매기므로 대물세로 본다 · 능력원칙과 편익원칙을 함께 구현할 수 있고 자산수익률이 노동수익률보다 높다면 자산과세를 강화할 때 소득분배가 개선된다 · 지방세의 근간으로 삼으면 지역 사이 세원 차이로 재정불균형이 커질 수 있다"],["부동산 조세","우리나라는 취득할 때 지방세인 취득세를, 보유할 때 재산세와 종합부동산세를, 양도할 때 국세인 양도소득세를 걷는다"],["과세와 부동산 가격","부동산 공급탄력성이 0이면 과세해도 초과부담이 없고 보유세를 올리면 자본화로 부동산 가격이 내린다 · 양도소득세는 팔기를 미루게 하는 동결효과로 거래를 위축시킨다"]]}],"10":[{"t":"table","title":"분배 정의론","head":["학자","주장"],"rows":[["벤담의 공리주의","효용 총합이 가장 큰 분배를 바람직하다고 보아 불균등한 분배도 정당화할 수 있다"],["에지워스","효용함수가 같고 소득의 한계효용이 체감하며 총소득이 고정되면 완전 균등분배가 최적이라고 했다"],["러너","누가 어떤 효용함수를 가졌는지 모르는 동등확률 아래서는 효용함수가 서로 달라도 균등분배가 최적이라고 보았다"],["롤즈","가장 가난한 사람의 후생을 최대로 하는 최소극대화 원칙보다 동등한 자유의 원칙을 앞세웠다"],["노직","결과보다 절차의 정의를 중시해 정당한 절차를 거치지 않았다면 균등분배도 정당하지 않다고 보았다"]]},{"t":"table","title":"불평등 지표","head":["지표","내용"],"rows":[["로렌츠곡선","하위 몇 %가 전체 소득의 몇 %를 갖는지 이은 곡선으로 대각선에 가까울수록 평등하고 서수적 평가라서 곡선이 교차하면 비교할 수 없다"],["지니계수","대각선과 로렌츠곡선 사이 면적을 대각선 아래 삼각형 면적으로 나눈 값으로 0(완전 평등)에서 1 사이다 · 곡선이 교차해도 숫자 하나로 비교할 수 있지만 그 결과는 곡선의 모양 차이를 다 담지 못한다"],["5분위배율","상위 20% 소득점유율을 하위 20% 점유율로 나눈 값이라 완전 균등이면 1이고 클수록 불평등하다"],["십분위분배율","하위 40% 점유율을 상위 20% 점유율로 나눈 값이라 완전 균등이면 2이고 클수록 평등하다"],["달튼의 평등지수","공리주의 사회후생함수에서 실제 후생을 균등분배 때의 후생으로 나눈 값으로 1에 가까울수록 평등하다"],["앳킨슨지수","1 − (균등분배대등소득/평균소득)으로 0이면 완전 평등이고 사회후생함수라는 가치판단을 명시적으로 깔고 있어 같은 분배라도 함수에 따라 값이 달라진다 · W = Y₁ × Y₂, 소득이 16과 4이면 W = 64라 균등분배대등소득은 8, 평균은 10이고 지수는 0.2다 · 소득 합만 보는 공리주의 함수에서는 균등분배대등소득이 평균소득과 같아 지수가 0이다"]]},{"t":"vs","title":"현금·현물·가격보조","cols":[{"name":"현금(소득)보조","items":["상대가격을 바꾸지 않아 대체효과가 없고 같은 돈이면 소비자 효용이 현물보조보다 같거나 높다"]},{"name":"현물보조","items":["가치재 소비를 늘리려는 목적에 잘 맞고 규모의 경제가 있는 재화에 유리하지만 행정·운영비가 많이 든다"]},{"name":"가격보조","items":["대체효과와 소득효과를 함께 일으켜 해당 재화 소비를 가장 크게 늘리지만 비효율을 낳는다"]}]},{"t":"table","title":"복지제도","head":["구분","내용"],"rows":[["부의 소득세","보조금 S = m − tE(m은 기초수당, t는 한계세율, E는 번 소득)이므로 E = m/t에서 보조가 끊긴다 · m = 50만원, t = 0.2이면 250만원에서 끊기고 t를 내리면 보조금은 늘어난다 · 재원이 고정되면 m을 올릴 때 t도 올려야 하며 여가가 정상재면 소득효과와 대체효과가 모두 노동공급을 줄이지만 자격 심사가 필요 없어 행정이 단순하다"],["근로장려세제","일하는 저소득 가구에 소득과 재산 요건을 따져 장려금을 주며 우리나라는 가구 구성에 따라 혜택을 달리한다 · 점증구간에서는 대체효과가 노동공급을 늘리고 소득효과가 줄이며 암묵적 한계세율이 0인 평탄구간에는 대체효과가 없다 · 점감구간에서는 소득 1원당 가처분소득 증가가 작아져 두 효과 모두 노동공급을 줄이지만 전체로는 부의 소득세나 공공부조보다 근로의욕을 더 북돋는다"],["공적연금","연금 기대는 자산대체효과로 민간저축을 줄이고 은퇴효과·상속효과·인식효과는 저축을 늘린다 · 적립방식은 민간저축이 줄어도 기금 적립이 이를 메워 국민저축이 줄지 않고 부과방식은 근로세대가 노년세대를 부양해 세대 간 재분배와 세대 간 공평성 문제가 생긴다 · 공적연금은 강제가입으로 역선택을 막고 근시안적인 노후 준비를 보완한다"],["사회보험과 공공부조","우리나라 사회보험은 국민연금·건강보험·고용보험·산재보험·노인장기요양보험 5가지로 보험료가 주 재원이고 공공부조(국민기초생활보장 등)는 세금으로 기여와 관계없이 대상자를 지원한다 · 산재보험료는 사용자가 전액 내고 기초연금은 조세로 충당한다"],["의료보험 도덕적 해이","병원 방문 수요가 P = 400 − Q이고 비용 100에 본인부담 20이면 방문이 300에서 380으로 늘어 도덕적 해이의 후생비용은 ½ × 80 × 80 = 3,200이다"]]}],"11":[{"t":"table","title":"정부 간 기능 배분","head":["구분","내용"],"rows":[["재정 3기능의 배분","머스그레이브의 재정 3기능 가운데 소득분배와 경제안정은 중앙정부가, 자원배분 일부는 지방정부가 맡는 것이 바람직하다"],["중앙정부가 공급하는 공공재","편익이 미치는 공간적 범위가 전국이거나 외부성이 지역 경계를 넘거나 규모의 경제가 크거나 무임승차 가능성이 높은 공공재는 중앙정부가 공급한다"],["중앙정부와 지방정부의 몫","국방·외교는 중앙정부, 쓰레기 수거·거리청소처럼 조세부담과 편익의 연계가 강한 것은 지방정부 몫이다"]]},{"t":"vs","title":"오우츠 정리와 티부 모형","cols":[{"name":"오우츠의 분권화 정리","items":["공급비용이 같고 외부성과 규모의 경제가 없다면 지방공공재는 지역마다 선호에 맞춰 지방정부가 공급하는 것이 중앙정부의 획일적 공급보다 효율적이라고 했다","지방정부는 주민 선호 정보를 더 싸게 얻는다","한 지역의 공급이 다른 지역에 외부성을 주면 분권적 공급이 비효율적일 수 있다"]},{"name":"티부 모형","items":["지역사회가 여럿이고 주민이 원하는 지역으로 옮겨 가는 발에 의한 투표로 지방공공재가 효율적으로 배분된다고 했다","전제는 완전한 이동성, 지역에 대한 완전한 정보, 충분히 많은 지역사회, 지방정부 행동의 외부성 없음, 규모의 경제 없음, 재원은 재산세다"]}]},{"t":"vs","title":"지방분권과 보조금","cols":[{"name":"지방분권의 장단점","items":["지역 특성과 주민 욕구를 반영한 정책을 시도하기 쉽고 자치단체 사이 경쟁으로 효율적 생산을 촉진한다","지역 간 재정능력 차이로 격차가 커질 수 있고 외부성이 있으면 공급이 비효율적이 된다","중앙정부 교부금에 기대면 지방의 재정자립도는 낮아진다"]},{"name":"보조금 유형별 효과","items":["무조건부(비대응) 보조금은 소득효과만 일으켜 공공재와 사적재 소비를 함께 늘리고 일부는 주민 조세부담을 덜어 주므로 같은 금액이면 후생 면에서 가장 낫다","대응보조금은 공공재의 상대가격을 낮춰 대체효과까지 일으키므로 공공재 소비를 더 크게 늘리지만 선택을 왜곡하고 사적재 소비는 늘 수도 줄 수도 있다","조건부 비대응보조금도 주민의 공공재 소비와 후생을 늘린다"]}]},{"t":"table","title":"끈끈이 효과와 지방재정","head":["구분","내용"],"rows":[["끈끈이 효과","보조금이 들어와도 지방세가 줄지 않고 지방정부 지출이 같은 금액의 주민소득 증가 때보다 더 크게 느는 현상이다"],["재정착각","주민이 교부금을 공공재 생산비(한계조세가격)가 내린 것으로 잘못 아는 재정착각과 관료의 예산극대화 동기가 원인으로 꼽힌다 · 관료가 교부금을 받은 사실을 주민에게 알리지 않을 때 이런 착각이 생긴다"],["지방교부세","용도가 정해지지 않은 무조건부 교부금으로 보통교부세·특별교부세·부동산교부세·소방안전교부세가 있다"],["국고보조금과 조정교부금","국고보조금은 용도가 정해진 조건부 보조금이고 조정교부금은 상위 자치단체가 하위 자치단체에 주는 돈이다 · 교부세와 보조금은 의존재원이라 재정자립도를 높이지 못하며 자율적 운영에는 교부세가 국고보조금보다 낫다"],["지방세와 중앙집권화율","우리나라 지방세 규모는 국세보다 작고 국세든 지방세든 세목은 법률에 근거해야 신설할 수 있다 · 부동산 경기는 취득세 등을 거쳐 지방재정의 규모와 안정성을 흔든다 · 중앙집권화율은 정부 총지출 가운데 중앙정부 직접지출의 비율로 분권 정도를 간접적으로 보여 주며 지방정부가 보조금으로 공급하는 몫은 지방 지출로 잡혀 중앙집권화 정도가 과소평가된다"]]}],"12":[{"t":"table","title":"재정의 기능과 재정승수","head":["구분","내용"],"rows":[["재정의 기능","공공재·외부성 같은 시장실패를 바로잡는 자원배분, 수평적·수직적 공평을 높이는 소득분배, 경제안정의 세 기능을 맡는다"],["자동안정장치","누진소득세와 실업보험 같은 자동안정장치는 경기에 따라 저절로 작동해 내부시차가 없으므로 시차 면에서는 재량적 재정정책보다 낫다 · 경기가 과열되면 특정기간 조세감면을 폐지하는 식으로 투자 유인을 줄인다"],["재정승수","한계소비성향이 c이면 정부지출승수는 1/(1 − c), 감세승수는 c/(1 − c)라 같은 금액이면 정부지출 증가의 총수요 효과가 크다"],["재정승수 계산","C = 200 + 0.8(Y − T), I = 400, G = T = 400이면 Y = 3,400이고 완전고용 4,000까지 600이 모자라므로 정부지출은 120(승수 5), 감세는 150(승수 4)이 필요하다 · 정부지출과 세금을 같은 금액만큼 줄이면 적자는 그대로지만 총수요는 준다"]]},{"t":"table","title":"적자재정과 국채","head":["구분","내용"],"rows":[["케인즈학파","국채로 세금을 줄여 주면 총수요가 늘어난다고 본다"],["통화주의자","국채발행이 이자율을 올려 민간투자를 밀어내는 구축효과가 크다고 보며 그 효과는 경기침체기보다 호황기에 더 크다"],["리카도-배로의 대등정리","정부지출이 일정하면 조세로 조달하든 국채로 조달하든 사람들이 미래 세금에 대비해 저축하므로 총수요·국민저축·이자율이 변하지 않는다는 주장이다"],["시중 소화","국채를 시중에서 소화하면 이자율이 올라 민간투자가 줄어든다 · 이자율 상승으로 해외 자본이 들어오면 원화가 절상되어(환율 하락) 경상수지가 나빠진다"],["중앙은행 인수","이자율은 오르지 않고 통화량이 늘어 총수요 증대효과가 더 크지만 인플레이션을 부른다"],["러너의 전통적 견해","내부채무는 국민끼리 주고받는 것이라 미래세대의 부담이 아니고 외부채무는 미래세대에 부담이 넘어간다 · 중복세대모형에서는 국가채무의 부담이 미래세대로 전가된다 · 민간이 가진 국채 잔액이 늘어 부유해졌다고 느껴 소비가 느는 현상을 러너효과라 한다"]]},{"t":"table","title":"정부지출 팽창","head":["구분","내용"],"rows":[["바그너 법칙","1인당 소득이 늘 때 공공부문이 민간부문보다 빠르게 커진다는 것으로 공공서비스 수요의 소득탄력성이 크기 때문이다"],["브라운-잭슨","이를 중위투표자의 선택과 묶어 중위투표자의 공공서비스 수요 소득탄력성이 충분히 크면 정부지출 비중이 커진다고 했다"],["보몰효과","노동집약적인 공공부문의 생산성이 민간보다 느리게 올라 공공서비스 생산비가 상대적으로 빠르게 오르는 현상이다"],["피코크-와이즈만","전쟁 같은 사회적 격변기에 국민이 더 높은 세부담을 받아들이는 전위효과로 정부지출이 한 단계 높아져 내려오지 않는다고 했다"],["부캐넌","정부지출의 편익은 바로 느끼지만 조세부담은 과소평가하는 재정착각과 대의민주체제의 특성으로 정부가 커진다는 리바이어던 가설을 냈다 · 관료의 예산극대화 성향도 지출 팽창의 원인이다"]]},{"t":"table","title":"조세지출과 예산제도","head":["구분","내용"],"rows":[["조세지출","세법상 감면으로 걷지 않게 된 세수로 특별감가상각·투자세액공제·기부금 소득공제가 예이고 보조금 지급은 재정지출이다"],["조세지출예산제도","조세지출 남발을 막으려고 그 규모를 예산처럼 공개하는 제도다 · 조세지출이 정당하려면 특정 행위를 촉진할 필요, 정부가 개입할 이유, 조세지출이 최선의 수단인지가 검증되어야 한다"],["품목별 예산제도","지출항목별로 편성해 통제에 강하지만 비슷한 일을 하는 부서 사이의 중복을 막기 어렵다"],["성과주의 예산제도","사업의 산출을 중심으로 편성한다"],["영기준 예산제도","매년 모든 사업을 처음부터 다시 평가해 점증주의를 벗어나지만 시간과 비용이 많이 든다"],["프로그램 예산제도","우리나라는 비슷한 업무를 묶어 편성하는 프로그램 예산제도를 2007년부터 도입했다"]]}]};
