(window.TNQ=window.TNQ||[]).push({"terms":{"한계대체율":{"d":"소비자가 효용을 같게 유지하며 한 재화를 더 얻기 위해 포기할 의사가 있는 다른 재화의 양이다.","r":[]},"한계기술대체율":{"d":"생산량을 유지하며 한 생산요소를 줄일 때 다른 요소로 대체해야 하는 비율이다.","r":[]},"한계변환율":{"d":"생산가능곡선 위에서 한 재화를 더 생산하기 위해 포기해야 하는 다른 재화의 양이다.","r":[]},"파레토 개선":{"d":"다른 사람의 효용을 줄이지 않고 적어도 한 사람의 효용을 높이는 변화이다.","r":[]},"초기부존":{"d":"경제주체가 거래를 시작하기 전에 가지고 있는 재화와 자원의 양이다.","r":[]},"사회후생함수":{"d":"개인들의 효용을 사회 전체의 후생으로 모으는 함수이다. 가치기준에 따라 형태가 달라진다.","r":[]},"역선택":{"d":"정보가 부족한 쪽이 불리한 상대와 거래하게 되는 현상이다. 위험이 큰 사람이 보험에 더 많이 가입하는 것이 예이다.","r":[]},"도덕적 해이":{"d":"보험에 가입한 뒤 위험을 피하려는 노력을 줄여 사고 확률이 높아지는 행동 변화이다.","r":[]},"비배제성":{"d":"대가를 내지 않은 사람을 소비에서 막을 수 없는 재화의 성질이다.","r":[]},"가치재":{"d":"사적재이지만 정부가 바람직하다고 판단해 소비를 장려하는 재화이다.","r":[]},"사무엘슨 조건":{"d":"공공재의 효율적 공급을 위해 개인들의 한계편익의 합이 한계비용과 같아야 한다는 조건이다.","r":[]},"린달 모형":{"d":"각자의 부담비율을 제시해 자발적 합의로 공공재 공급량과 비용 분담을 정하는 모형이다.","r":[]},"중위투표자":{"d":"단순다수결에서 선호의 중간에 위치해 결과를 좌우하는 투표자이다.","r":[]},"투표의 역설":{"d":"선호가 엇갈리면 다수결 결과가 순환해 이행성이 깨지는 현상이다.","r":["꽁도세 승자"]},"꽁도세 승자":{"d":"다른 모든 대안과 일대일 다수결로 겨뤄 전부 이기는 대안이다.","r":["투표의 역설"]},"보다투표":{"d":"순위별로 점수를 매겨 합산해 결과를 정하는 투표 방식이다.","r":[]},"로그롤링":{"d":"서로의 사업에 찬성표를 교환해 각자의 이익을 얻는 투표거래이다.","r":[]},"니스카넨":{"d":"관료가 예산을 극대화한다고 보고 공공서비스가 과다 공급되는 이유를 설명한 학자이다.","r":[]},"재량예산":{"d":"관료가 실제 비용을 넘겨 확보하는 여유 예산이다.","r":[]},"편익·비용비율":{"d":"사업의 편익 현재가치를 비용 현재가치로 나눈 값으로 1보다 크면 채택한다.","r":[]},"내부수익률":{"d":"순현재가치를 0으로 만드는 할인율이다. 사회적 할인율보다 크면 사업이 채택된다.","r":[]},"잠재가격":{"d":"시장가격이 자원의 사회적 기회비용을 제대로 반영하지 못할 때 이를 보정해 쓰는 가격이다.","r":[]},"헤도닉가격법":{"d":"주택가격 같은 시장자료를 분석해 환경 속성의 가치를 추정하는 방법이다.","r":["여행비용법"]},"여행비용법":{"d":"방문에 드는 비용으로 자연환경의 가치를 추정하는 방법이다.","r":["헤도닉가격법"]},"비용효과분석":{"d":"편익을 화폐로 재기 어려울 때 같은 목표를 가장 적은 비용으로 달성하는 대안을 고르는 분석이다.","r":[]},"편익원칙":{"d":"정부 서비스로부터 얻는 편익만큼 조세를 부담해야 한다는 과세 원칙이다.","r":[]},"능력원칙":{"d":"경제적 능력에 따라 조세를 부담하게 해야 한다는 과세 원칙이다.","r":[]},"수평적 공평":{"d":"같은 능력을 가진 사람이 같은 세금을 내야 한다는 원칙이다.","r":["수직적 공평"]},"수직적 공평":{"d":"능력이 큰 사람이 더 많은 세금을 내야 한다는 원칙이다.","r":["수평적 공평"]},"법적 귀착":{"d":"법에서 정한 납세의무자에게 세금이 부과되는 것이다.","r":["경제적 귀착"]},"경제적 귀착":{"d":"시장 조정을 거쳐 실제로 세금을 부담하는 사람에게 부담이 돌아가는 것이다.","r":["법적 귀착"]},"전방전가":{"d":"조세 부담이 가격 상승을 통해 소비자에게 옮겨지는 것이다.","r":[]},"초과부담":{"d":"조세로 인한 소비자와 생산자의 후생 감소분이 조세수입보다 큰 부분이다. 대체재가 적을수록 커진다.","r":[]},"정액세":{"d":"소득이나 행동과 관계없이 일정 금액을 부과하는 조세이다. 민간 의사결정을 왜곡하지 않는다.","r":[]},"램지 규칙":{"d":"세수를 얻으면서 초과부담을 최소화하도록 보상수요량이 같은 비율로 줄게 세율을 정하는 규칙이다.","r":["역탄력성 원칙"]},"역탄력성 원칙":{"d":"재화 간 수요가 독립적일 때 세율을 수요의 가격탄력성에 반비례하게 정하는 원칙이다.","r":["램지 규칙"]},"소득공제":{"d":"과세소득에서 일정 금액을 빼 주는 제도이다. 고소득층일수록 세 부담 경감 효과가 크다.","r":[]},"세액공제":{"d":"산출된 세액에서 일정 금액을 직접 빼 주는 제도이다.","r":[]},"자본의 사용자비용":{"d":"자본재를 보유하는 데 드는 기회비용으로 투자 결정에 영향을 준다.","r":[]},"면세":{"d":"그 단계의 매출에 세금을 면제하되 앞 단계 매입세액은 환급하지 않는 부분면세이다.","r":[]},"대물세":{"d":"사람의 사정을 고려하지 않고 물건을 기준으로 과세하는 조세이다.","r":[]},"로렌츠곡선":{"d":"인구의 누적 비율과 소득의 누적 비율의 관계를 나타낸 곡선이다. 교차하면 불평등도를 비교하기 어렵다.","r":[]},"부의 소득세":{"d":"소득이 기준에 못 미치는 사람에게 세금 대신 보조금을 주고 소득이 늘면 보조금을 줄이는 제도이다.","r":[]},"공공부조":{"d":"국가가 보험료 없이 조세를 재원으로 생활이 어려운 사람에게 제공하는 지원이다.","r":[]},"재정착각":{"d":"주민이 공공서비스 비용이나 보조금의 크기를 잘못 인식해 정부 지출이 늘어나는 현상이다.","r":[]},"자동안정장치":{"d":"경기에 따라 정부 개입 없이 저절로 작동해 총수요 변동을 줄여 주는 제도이다.","r":[]},"구축효과":{"d":"정부의 국채 발행 등으로 이자율이 올라 민간투자가 줄어드는 현상이다.","r":[]},"러너효과":{"d":"국채 잔액이 늘어 부유해졌다고 느낀 민간의 소비가 늘어나는 현상이다.","r":[]},"전위효과":{"d":"사회적 격변기에 정부지출이 늘어난 수준이 위기 후에도 유지되는 현상이다.","r":[]},"조세지출":{"d":"조세 감면 등으로 포기한 조세수입으로 보조금과 같은 효과가 나는 제도이다.","r":[]},"외부성":{"d":"한 경제주체의 행동이 시장 거래 없이 제3자에게 이득이나 손실을 주는 현상이다. 시장 실패의 원인이 된다.","r":[]},"실질적 외부성":{"d":"개인의 행동이 제3자의 생산이나 효용에 실제로 영향을 주어 자원배분을 비효율로 만드는 외부성이다.","r":[]},"금전적 외부성":{"d":"행동이 상대가격 변동을 통해 타인에게 영향을 주는 외부성이다. 자원배분의 비효율을 일으키지 않는다.","r":[]},"긍정적 외부성":{"d":"제3자에게 대가 없이 이득을 주는 외부성이다. 재화가 사회적 최적 수준보다 적게 생산된다.","r":[]},"부정적 외부성":{"d":"제3자에게 대가 없이 손실을 주는 외부성이다. 재화가 사회적 최적 수준보다 많이 생산된다.","r":[]},"내부화":{"d":"외부성에 따른 비용이나 편익을 당사자의 의사결정에 반영시키는 것이다.","r":[]},"교정세":{"d":"외부성을 시정하기 위해 부과하는 조세이다. 피구세라고도 한다.","r":[]},"피구세":{"d":"부정적 외부성이 있는 재화에 한계외부피해만큼 부과하는 조세로 사회적 최적 생산량을 이끈다.","r":[]},"코즈정리":{"d":"거래비용이 없고 재산권이 명확하면 누구에게 재산권이 있든 자발적 협상으로 효율적 자원배분이 가능하다는 정리이다.","r":[]},"사적한계편익":{"d":"소비자가 재화를 한 단위 더 소비할 때 얻는 개인의 편익이다.","r":[]},"사적 한계 비용":{"d":"생산자가 재화를 한 단위 더 생산할 때 부담하는 비용이다.","r":[]},"한계 외부 피해":{"d":"재화를 한 단위 더 생산할 때 제3자에게 발생하는 추가적 피해이다.","r":[]},"배출권 시장":{"d":"오염물질 배출 권리를 거래하는 시장이다. 균형에서 각 기업의 한계저감비용이 같아진다.","r":[]},"한계저감비용":{"d":"오염물질 배출을 한 단위 더 줄이는 데 드는 추가 비용이다.","r":[]},"소득효과":{"d":"가격이나 세율 변화로 실질소득이 변해 수요나 공급이 변하는 효과이다.","r":[]},"대체효과":{"d":"상대가격 변화로 상대적으로 싸진 쪽으로 선택이 옮겨 가는 효과이다.","r":[]},"비왜곡적":{"d":"조세가 상대가격을 바꾸지 않아 경제주체의 선택을 왜곡하지 않는 성질이다.","r":[]},"선형누진소득세":{"d":"한계세율이 일정하고 정액의 공제를 두어 평균세율이 소득에 따라 올라가는 소득세이다.","r":[]},"한계세율":{"d":"소득이 한 단위 증가할 때 추가로 내는 세금의 비율이다.","r":[]},"수평적 공평성":{"d":"경제적 능력이 같은 사람에게 같은 세금을 부과해야 한다는 원칙이다.","r":[]},"수직적 공평성":{"d":"경제적 능력이 큰 사람에게 더 많은 세금을 부과해야 한다는 원칙이다.","r":[]},"후방굴절":{"d":"임금이 일정 수준 이상 오르면 소득효과가 대체효과보다 커서 노동공급이 줄어드는 노동공급곡선의 모양이다.","r":[]},"보상수요곡선":{"d":"가격 변화에 따른 소득효과를 제거하고 대체효과만을 나타내는 수요곡선이다. 초과부담 측정에 사용한다.","r":[]},"보상노동공급곡선":{"d":"소득효과를 제거하고 대체효과만을 나타내는 노동공급곡선이다.","r":[]},"램지규칙":{"d":"조세수입이 일정할 때 초과부담을 최소화하도록 수요의 가격탄력성에 반비례하여 세율을 정해야 한다는 규칙이다.","r":[]},"램지가격설정":{"d":"수요의 가격탄력성에 반비례해 가격을 정해 결손을 최소한의 비효율로 메우는 가격 방식이다.","r":[]},"역탄력성 법칙":{"d":"최적 물품세율이 수요의 가격탄력성에 반비례해야 한다는 법칙이다.","r":[]},"포괄소득세제":{"d":"경제적 능력의 증가분을 모두 소득으로 보아 과세하는 제도이다. 헤이그-사이먼즈의 정의에 따른다.","r":[]},"헤이그-사이먼즈":{"d":"소득을 일정 기간 소비와 순자산 증가의 합으로 정의하는 포괄소득 개념이다.","r":[]},"동등희생의 원칙":{"d":"각 납세자가 조세로 인해 입는 효용 희생이 같아야 한다는 원칙이다.","r":[]},"이자소득세":{"d":"이자 소득에 부과하는 조세이다. 부과하면 현재소비의 상대가격이 상승한다.","r":[]},"사용자비용":{"d":"자본을 한 기간 사용하는 데 드는 비용으로 이자, 감가상각, 조세 효과를 포함한다.","r":[]},"자본스톡":{"d":"일정 시점에 경제 안에 존재하는 자본재의 총량이다.","r":[]},"가속상각제도":{"d":"초기에 감가상각을 많이 인정해 투자의 세 부담을 줄여 주는 제도이다.","r":[]},"투자세액공제":{"d":"투자액의 일정 비율을 법인세 등에서 직접 빼 주는 제도이다.","r":[]},"한계실효세율":{"d":"투자에서 추가로 얻는 수익에 조세가 부과되는 실제 비율이다. 높을수록 투자가 위축된다.","r":[]},"경제적 이윤":{"d":"총수입에서 기회비용까지 포함한 모든 비용을 뺀 이윤이다.","r":[]},"사내유보":{"d":"법인이 이윤을 배당하지 않고 사내에 쌓아 두는 것이다.","r":[]},"귀속이자":{"d":"기업이 자기자본에 대해 지급한 것으로 보는 이자이다. 대부분 국가에서 비용으로 인정하지 않는다.","r":[]},"완전통합방식":{"d":"법인세를 개인소득세의 선급분으로 보아 법인과 주주를 하나로 보고 과세하는 방식이다.","r":[]},"배당세액공제":{"d":"배당소득에 이미 부과된 법인세를 개인 소득세에서 빼 주는 제도이다.","r":[]},"배당무의미성이론":{"d":"완전자본시장에서는 배당정책이 기업가치에 영향을 주지 못한다는 이론이다.","r":[]},"완전손실상계제도":{"d":"투자 손실을 다른 소득과 합산해 세액을 줄여 주는 제도이다. 정부가 손실을 분담하는 효과가 있다.","r":[]},"영세율":{"d":"부가가치세에서 일정한 거래에 0%의 세율을 적용하고 매입세액을 환급해 주는 제도이다.","r":[]},"매입세액 공제":{"d":"부가가치세에서 매출세액에서 매입세액을 빼서 납부세액을 구하는 방식이다.","r":[]},"수직적 통합":{"d":"생산과 유통 등 여러 단계를 한 기업이 맡는 것이다.","r":[]},"총소득형 부가가치세":{"d":"자본재 구입을 즉시 공제하지 않고 감가상각만 공제하지 않는 형태의 부가가치세이다.","r":[]},"순소득형 부가가치세":{"d":"총수입에서 중간투입물 구입비용과 자본재 감가상각비를 뺀 것에 과세하는 부가가치세이다.","r":[]},"공급탄력성":{"d":"가격 변화에 대한 공급량 변화의 정도이다. 0이면 공급량이 변하지 않는다.","r":[]},"비용편익분석":{"d":"공공사업의 편익과 비용을 화폐 가치로 비교해 사업의 타당성을 평가하는 방법이다.","r":[]},"순현재가치":{"d":"편익의 현재가치에서 비용의 현재가치를 뺀 값이다. 0보다 크면 사업이 타당하다.","r":[]},"사회적 할인율":{"d":"미래의 편익과 비용을 현재가치로 환산하기 위해 사용하는 할인율이다.","r":[]},"파레토기준":{"d":"아무도 손해를 보지 않고 일부가 이득을 보면 개선으로 평가하는 기준이다.","r":[]},"조건부보조금":{"d":"중앙정부가 사용 용도를 정해 지방정부에 교부하는 보조금이다.","r":[]},"무조건부보조금":{"d":"용도를 정하지 않고 지방정부에 교부하는 보조금이다. 소득효과를 발생시킨다.","r":[]},"대응교부금":{"d":"지방정부 지출액에 비례하여 지급하는 교부금이다. 대체효과를 발생시킨다.","r":[]},"끈끈이 효과":{"d":"보조금이 주민의 소득 증가보다 지방정부 지출을 훨씬 더 늘리는 현상이다.","r":[]},"지방교부세":{"d":"중앙정부가 재정력이 부족한 지방정부에 용도를 정하지 않고 교부하는 재원이다.","r":[]},"국고보조금":{"d":"중앙정부가 특정 사업을 위해 지방정부에 지급하는 용도 지정 보조금이다.","r":[]},"중앙집권화율":{"d":"정부 총지출 중 중앙정부 지출이 차지하는 비율로 분권 수준을 나타낸다.","r":[]},"발에 의한 투표":{"d":"주민이 선호하는 공공서비스와 조세 조합의 지역으로 이동하는 것을 투표에 빗댄 말이다.","r":[]},"분권화 정리":{"d":"지방공공재의 편익이 해당 지역에 한정되면 지방정부가 공급하는 것이 중앙정부보다 효율적이라는 정리이다.","r":[]},"비경합성":{"d":"한 사람의 소비가 다른 사람의 소비를 줄이지 않는 성질이다.","r":[]},"클럽재":{"d":"배제성이 있고 소비에서 경합성이 없는 재화이다.","r":[]},"순수공공재":{"d":"비경합성과 비배제성을 모두 가진 재화이다. 소비자 추가에 따른 한계비용이 0이다.","r":[]},"수요표출메커니즘":{"d":"공공재 수요를 참되게 드러내게 하는 장치이다. 클라크세가 예이다.","r":[]},"클라크세":{"d":"자신의 선호 표출이 결과를 바꿀 때 그 피해를 세금으로 부담시켜 진실한 선호 표출을 유도하는 조세이다.","r":[]},"우월전략":{"d":"상대방의 선택과 관계없이 자신에게 가장 유리한 전략이다.","r":[]},"내쉬균형":{"d":"상대의 전략이 주어졌을 때 누구도 자기 전략을 바꿀 유인이 없는 상태이다.","r":[]},"한계비용가격설정":{"d":"가격을 한계비용에 일치시키는 방식이다. 규모의 경제 하에서는 결손이 생긴다.","r":[]},"평균비용가격설정":{"d":"가격을 평균비용에 일치시켜 경제적 이윤을 0으로 하는 방식이다.","r":[]},"최대부하가격설정":{"d":"수요가 몰리는 성수기에 더 높은 가격을 받는 방식이다. 비성수기에는 한계비용에 맞춘다.","r":[]},"이부가격제도":{"d":"기본요금과 사용량에 비례한 추가 요금을 함께 부과하는 가격 제도이다.","r":[]},"정보비대칭":{"d":"거래 당사자 사이에 가진 정보의 양이나 질이 달라 시장실패를 낳는 상태이다.","r":[]},"실업급여":{"d":"고용보험에서 실직한 사람에게 일정 기간 지급하는 급여이다.","r":[]},"가처분소득":{"d":"소득에서 세금 등을 빼고 소비와 저축에 자유로이 쓸 수 있는 소득이다.","r":[]},"상속효과":{"d":"연금 제도 아래에서 자녀에게 물려줄 재산을 늘리려고 민간저축이 증가하는 효과이다.","r":[]},"자산대체효과":{"d":"연금 급여를 기대해 개인이 저축을 줄이는 효과이다. 재산대체효과라고도 한다.","r":[]},"포괄수가제":{"d":"진료 행위와 관계없이 질병별로 정해진 진료비를 지급하는 방식이다. 과잉진료를 줄이나 의료 품질 저하가 우려된다.","r":[]},"행위별수가제":{"d":"진료 행위별로 건당 진료비를 합산해 지급하는 방식이다. 과잉진료 가능성이 있다.","r":[]},"적립방식":{"d":"가입자가 낸 보험료를 적립해 두었다가 본인이 연금으로 받는 재원 조달 방식이다. 세대 내 재분배가 일어난다.","r":[]},"부과방식":{"d":"현재 근로세대가 낸 보험료로 현재 수급자의 연금을 지급하는 방식이다. 세대 간 재분배가 일어난다.","r":[]},"공적연금":{"d":"국가가 운영하는 연금으로, 국민연금과 직역연금이 있다.","r":[]},"직역연금":{"d":"공무원, 군인, 사립학교교직원 등 특정 직역 종사자가 가입하는 연금이다.","r":[]},"사회보험":{"d":"국가가 보험료를 재원으로 질병, 실업, 노령 등 위험에 대비해 운영하는 보험이다. 강제가입이다.","r":[]},"온정적 간섭주의":{"d":"개인이 스스로 판단하면 합리적 선택을 못한다고 보고 정부가 개인의 선택에 개입하는 입장이다.","r":[]},"국민기초생활보장제도":{"d":"생활이 어려운 사람에게 필요한 급여를 제공해 최저생활을 보장하는 우리나라 대표적 공공부조제도이다.","r":[]},"부양의무자":{"d":"수급자를 부양할 법적 의무가 있는 사람이다.","r":[]},"차상위계층":{"d":"최저생계비 바로 위 소득 수준인 계층으로 기초생활보장 수급자는 아닌 사람이다.","r":[]},"근로장려세제":{"d":"저소득 근로자 가구에 근로소득에 따라 현금을 지급하는 제도이다. 근로 유인과 생계 지원을 함께 목적으로 한다.","r":[]},"암묵적 한계세율":{"d":"소득이 늘 때 보조금이 줄어드는 비율로, 사실상의 한계세율 역할을 한다.","r":[]},"기초수당":{"d":"소득과 관계없이 모두에게 일정 금액을 지급하는 수당이다.","r":[]},"현물보조":{"d":"금전이 아니라 재화나 서비스로 지원하는 보조이다. 현금보조보다 행정비용이 많이 든다.","r":[]},"현금보조":{"d":"금전으로 지원하는 보조이다. 수혜자의 선택 자유가 크다.","r":[]},"가격보조":{"d":"재화 가격의 일부를 지원해 상대가격을 낮추는 보조로 소득효과와 대체효과를 일으킨다.","r":[]},"앳킨슨지수":{"d":"균등분배대등소득을 평균소득과 비교해 불평등을 재는 지수이다. 0에서 1 사이이고 사회적 가치판단에 따라 달라진다.","r":[]},"균등분배대등소득":{"d":"현재 분배 상태와 같은 사회후생을 주는 균등분배 상태의 1인당 소득이다.","r":[]},"지니계수":{"d":"로렌츠곡선에서 구한 불평등 지표이다. 0이면 완전 균등이고 클수록 불평등하다.","r":[]},"5분위분배율":{"d":"상위 20%의 소득점유비율을 하위 20%의 소득점유비율로 나눈 값이다.","r":[]},"십분위분배율":{"d":"하위 40%의 소득점유비율을 상위 20%의 소득점유비율로 나눈 값이다. 완전 균등이면 2이다.","r":[]},"공리주의":{"d":"사회 구성원의 효용 총합이 최대인 상태를 바람직하다고 보는 입장이다.","r":[]},"평등주의":{"d":"모든 사람에게 평등한 분배가 정의롭다고 보는 입장이다.","r":[]},"자유주의":{"d":"정부 간섭 없이 시장에서 결정된 분배를 바람직하다고 보는 입장이다.","r":[]},"최소극대화원칙":{"d":"사회에서 가장 불리한 사람의 효용을 최대로 하는 분배가 정의라는 롤스의 원칙이다.","r":[]},"효용가능경계":{"d":"사회가 주어진 자원으로 달성할 수 있는 개인 효용 조합의 최대 경계이다.","r":[]},"파레토최적":{"d":"다른 사람을 해치지 않고는 누구도 더 좋아질 수 없는 자원배분 상태이다.","r":[]},"후생경제학의 제1정리":{"d":"완전경쟁시장의 균형은 파레토 효율적이라는 정리이다.","r":[]},"경쟁균형":{"d":"완전경쟁시장에서 수요와 공급이 일치하는 균형 상태이다.","r":[]},"조건부거래시장":{"d":"불확실한 상태가 발생할 경우를 조건으로 한 거래시장이다. 애로우가 이를 설명했다.","r":[]},"사회무차별곡선":{"d":"사회후생이 같은 개인 효용 조합을 이은 곡선이다.","r":[]},"시장실패":{"d":"시장이 효율적 자원배분을 못 이루는 상태이다. 공공재, 외부성, 독점, 정보 비대칭이 원인이다.","r":[]},"정부실패":{"d":"정부 개입이 오히려 자원배분을 비효율적으로 만드는 현상이다.","r":[]},"자연독점":{"d":"규모의 경제로 한 기업이 생산하는 것이 효율적이어서 생기는 독점이다.","r":[]},"중립세":{"d":"민간의 의사결정을 왜곡하지 않는 조세이다.","r":[]},"종가세":{"d":"과세 대상의 가격에 일정 비율로 부과하는 조세이다.","r":[]},"종량세":{"d":"수량 단위당 일정 금액으로 부과하는 조세이다.","r":[]},"조세귀착":{"d":"조세의 실질적 부담이 최종적으로 누구에게 돌아가는가의 문제이다.","r":[]},"후방전가":{"d":"조세 부담이 요소 가격 하락 등을 통해 생산요소 공급자에게 옮겨지는 것이다.","r":[]},"자본화":{"d":"조세가 자산 가격에 반영되어 가격이 떨어지는 현상이다. 부담은 현재 소유자에게 귀착한다.","r":[]},"균형예산귀착":{"d":"조세와 정부지출을 함께 고려해 분배 효과를 분석하는 귀착 개념이다.","r":[]},"절대귀착":{"d":"다른 조세나 정부지출은 변하지 않는다고 보고 특정 조세만의 분배 효과를 분석하는 개념이다.","r":[]},"직접세":{"d":"법적 납세의무자와 실제 담세자가 같은 조세이다.","r":[]},"간접세":{"d":"납세의무자와 담세자가 달라 부담이 전가되는 조세이다.","r":[]},"목적세":{"d":"특정 목적에 쓰기 위해 부과하는 조세이다.","r":[]},"탈루소득":{"d":"탈세로 신고하지 않은 소득이다.","r":[]},"리바이어던가설":{"d":"정부가 세입 극대화를 추구해 정부 부문이 팽창한다는 가설이다.","r":[]},"영기준 예산제도":{"d":"전년도 예산과 관계없이 모든 사업을 처음부터 다시 평가해 편성하는 제도이다.","r":[]},"성과주의예산제도":{"d":"사업의 성과와 단위원가를 중심으로 편성하는 예산제도이다.","r":[]},"프로그램예산제도":{"d":"사업 목표별로 계획과 예산을 연결해 편성하는 예산제도이다.","r":[]},"보몰효과":{"d":"정부 서비스의 생산성 증가가 낮아 생산비용이 상대적으로 빠르게 늘어 정부지출이 증가하는 현상이다.","r":[]},"중위투표자 정리":{"d":"단일 정점 선호에서 다수결 결과는 중위투표자의 선호에 일치한다는 정리이다.","r":[]},"투표거래":{"d":"서로의 안건에 찬성표를 교환하는 행위이다. 선호의 강도를 반영한다.","r":[]},"꽁도세":{"d":"모든 대안을 둘씩 비교해 다수결로 이기는 대안을 선택하는 투표 방식이다.","r":[]},"니스카넨 모형":{"d":"관료가 예산 극대화를 추구한다고 보는 모형이다.","r":[]}},"notes":{"10억·20억·30억 예산안이면 중위인 20억이 꽁도세 승자다":"세 가지 예산안 중 한가운데에 놓인 20억이 다른 모든 안을 다수결로 이기는 꽁도세 승자입니다.","1 − (균등분배대등소득/평균소득)으로 0이면 완전 평등이고 사회후생함수라는 가치판단을 명시적으로 깔고 있어 같은 분배라도 함수에 따라 값이 달라진다":"앳킨슨지수는 1에서 균등분배대등소득과 평균소득의 비를 뺀 값으로 0이면 완전 평등하고, 사회후생함수 선택에 따라 값이 달라집니다.","1인당 소득이 늘 때 공공부문이 민간부문보다 빠르게 커진다는 것으로 공공서비스 수요의 소득탄력성이 크기 때문이다":"1인당 소득이 늘면 공공부문이 민간보다 빠르게 커진다는 바그너 법칙은 공공서비스 수요의 소득탄력성이 크다는 데 근거합니다.","1인 역수요에 인원수를 곱한 뒤 그룹끼리 더한다":"수요가 같은 사람이 여럿이면 1인 역수요에 인원수를 곱해 집단별 수요를 만든 뒤 집단끼리 수직으로 더합니다.","3√X_A = √X_B에서 X_A = 100, X_B = 900이고 W = 30이다":"롤즈 함수는 두 효용이 같아지도록 나누므로 몫이 100과 900이 되어 후생이 30입니다.","50년 뒤 순편익 −100억 원, 위험할인율 20%, 이자율 10%이면 현재가치는 −100억 원 × 1.2 ÷ 1.1⁵⁰이다":"50년 뒤 순편익에 위험할인율을 반영해 비용을 늘리고 이자율로 할인한 현재가치를 구하는 식입니다.","A: x > y > z, B: y > z > x, C: z > x > y처럼 선호가 엇갈리면 다수결 결과가 x > y > z > x로 순환해 이행성이 깨진다":"세 사람의 선호가 엇갈리면 다수결 결과가 원을 그리며 순환해 이행성이 깨지는 것이 투표의 역설입니다.","A·B가 각각 500을 배출하고 저감비용이 40 + q_A²/2, 30 + q_B²이면 한계저감비용은 q_A와 2q_B다":"두 기업의 한계저감비용은 비용함수를 감축량으로 미분해 구하며 각각 q_A와 2q_B가 됩니다.","A에 400, B에 300을 할당했다면 A는 100을 팔고 B는 100을 사므로 거래량은 100이다":"거래량은 할당량과 균형 배출량의 차이만큼이라, A가 팔고 B가 사는 물량이 같은 100입니다.","A의 비용이 X² + 4X, B의 비용이 Y² + 3Y + X라면 A의 생산이 B에 비용을 주므로 환경세는 A에 부과하고 합병·배출권 시장 개설·협상·수량규제도 효율적 배분 수단이 된다":"A의 생산이 B에 비용을 주므로 환경세를 A에 부과해야 하며, 합병·배출권 시장·협상·수량규제도 효율적 배분 수단입니다.","C = 200 + 0.8(Y − T), I = 400, G = T = 400이면 Y = 3,400이고 완전고용 4,000까지 600이 모자라므로 정부지출은 120(승수 5), 감세는 150(승수 4)이 필요하다":"소득 3,400이 완전고용 4,000에 600 모자라므로 승수 5를 적용해 정부지출 120, 승수 4를 적용해 감세 150이 필요합니다.","MC_X = 20, P_X = 25, MC_Y = 30, P_Y = 50이고 Y의 탄력성이 1이면 0.4 = k에서 X의 탄력성은 0.2 = 0.4/ε로 2다":"한 재화의 한계비용과 가격이 주어지면 비율을 구해 상수 k를 얻고, 이를 다른 재화에 적용해 탄력성을 구합니다.","MU_A = 4 − X, MU_B = 8 − 2X, MC = 2X이면 (4 − X) + (8 − 2X) = 2X에서 X = 2.4다":"한계편익의 합을 한계비용과 같게 놓고 풀면 최적 공급량이 2.4로 구해집니다.","NPV를 0으로 만드는 할인율이다":"내부수익률은 순현재가치를 영으로 만드는 할인율입니다.","P = 1,000, Q = 1,000, 수요·공급탄력성이 모두 0.1인 상품에 10% 종가세를 매기면 ½ × 0.01 × 1,000,000 × (0.01/0.2) = 250이다":"가격 1,000, 거래량 1,000에 탄력성이 모두 0.1인 상품에 10% 종가세를 매기면 초과부담이 250입니다.","PMB = 150 − Q, EMB = 30 − Q/4, PMC = Q이면 SMB = 180 − 1.25Q에서 최적 Q = 80이고 시장이 80을 고르게 하는 단위당 보조금은 10이다":"사회적 한계편익과 한계비용을 맞춘 최적 생산량 80에서 시장이 이를 고르도록 하는 단위당 보조금은 10입니다.","PMB = 600 − 4Q, PMC = 6Q, MD = 2Q이면 SMC = 8Q이고 600 − 4Q = 8Q에서 Q = 50, 세액은 2 × 50 = 100이다":"사적 한계비용에 외부 피해를 더해 사회적 한계비용을 구하고 편익과 맞춘 생산량 50에서 한계피해 100이 세액이 됩니다.","PQ(ε는 보상수요의 가격탄력성)가 된다":"보상수요의 가격탄력성을 이용해 초과부담을 가격과 거래량의 곱으로 나타내는 식입니다.","Q = 120 − 2P, Q = P에서 균형가격은 40이다":"수요와 공급이 만나는 균형가격은 수요식과 공급식을 연립해 40으로 구합니다.","Q = 300 − 3P, MC = Q + 10인 독점에 단위당 20을 과세하면 생산량이 54에서 42로 줄고 소비자 4, 독점기업 16을 부담한다":"독점기업에 단위당 20을 과세하면 생산량이 54에서 42로 줄고 소비자가 4, 기업이 16을 부담합니다.","Q_d = 50 − 2P, Q_s = 3P − 20에 생산자 과세 10이면 P가 14에서 20으로 오르고 Q = 10이라 세수 100, 후생손실은 ½ × 10 × 12 = 60이다":"세금 10을 생산자에게 매기면 균형가격이 14에서 20으로 오르고 거래량 10으로 세수 100, 후생손실 60이 계산됩니다.","SMB = PMB + EMB가 한계비용과 같은 곳이 최적이다":"이로운 외부성이 있으면 사회적 한계편익이 사적 편익에 외부편익을 더한 값이고, 그것이 한계비용과 같은 곳이 최적입니다.","T = −300 + 0.3Y이면 한계세율은 0.3으로 일정하고 평균세율 0.3 − 300/Y는 소득과 함께 오르지만 늘 0.3보다 낮으며 소득공제 1,000을 둔 선형누진세다":"이 세수함수는 한계세율이 일정하게 0.3이고 평균세율은 소득이 늘수록 오르되 0.3에는 못 미치는 선형누진세입니다.","W = U_A + U_B는 모두에게 같은 가중치를 주고 각자 소득의 한계효용이 같을 때 후생이 가장 크다":"공리주의 후생함수는 효용을 모두 같은 비중으로 더하므로, 각자 소득의 한계효용이 같도록 분배할 때 후생이 극대화됩니다.","W = Y₁ × Y₂, 소득이 16과 4이면 W = 64라 균등분배대등소득은 8, 평균은 10이고 지수는 0.2다":"소득이 16과 4일 때 후생 64에 해당하는 균등분배대등소득은 8이고 평균이 10이므로 앳킨슨지수는 0.2입니다.","X가 열등재라면 X재의 대체효과와 소득효과가 반대 방향으로 작용한다":"X가 열등재이면 대체효과는 X 소비를 줄이고 소득효과는 늘려서 두 효과가 서로 반대로 작용합니다.","X재 1,000단위를 U_A = 3√X_A, U_B = √X_B인 두 사람에게 나눌 때 3/(2√X_A) = 1/(2√X_B)에서 X_A = 900, X_B = 100이고 W = 100이다":"공리주의 후생을 극대화하려면 두 사람의 한계효용이 같아지는 지점을 찾으며, 이 계산에서 두 몫이 900과 100으로 나뉩니다.","X재에 물품세를 매기면 X의 상대가격이 올라 대체효과로 X는 줄고 Y는 는다":"물품세가 붙은 X재는 상대가격 상승 탓에 소비가 줄고 대신 Y재 소비가 늘어납니다.","Z_A = 100 − 20P, Z_B = 100 − 10P이고 MC = 3이면 역수요는 P_A = 5 − Z/20, P_B = 10 − Z/10이다":"두 사람의 수요를 가격에 대해 풀어 수직으로 합하는 과정이며 한계비용이 3이면 합산 역수요가 3과 같아지는 곳이 균형입니다.","m = 50만원, t = 0.2이면 250만원에서 끊기고 t를 내리면 보조금은 늘어난다":"기초수당이 50만원이고 한계세율이 0.2이면 250만원에서 보조가 끊기고, 세율을 내리면 보조금이 늘어납니다.","ε_dε_s/(ε_d + ε_s)로 세율의 제곱과 탄력성에 비례한다":"물품세 초과부담은 두 탄력성의 곱을 합으로 나눈 값을 쓰며 세율의 제곱과 탄력성에 비례합니다.","가격에 포함되어 소득세보다 조세저항이 작다":"부가가치세는 가격에 포함되어 있어 소득세보다 납세자가 느끼는 저항이 작습니다.","가격차별 독점도 같은 논리로 시장마다 MR = P(1 − 1/ε)를 같게 하므로 탄력성 2인 가정용이 1,200원이면 탄력성 3인 산업용은 900원이다":"가격차별 독점도 같은 논리로 시장마다 한계수입을 같게 하므로 탄력성이 큰 시장의 가격은 낮아집니다.","가결에 필요한 찬성 비율이 높을수록 의사결정비용은 커지고 반대자가 떠안는 외부비용은 작아진다":"찬성 비율을 높이면 합의에 시간과 비용이 더 들고, 대신 반대자가 입는 피해는 줄어듭니다.","가속상각·투자세액공제·법인세율 인하는 사용자비용을 낮추며 즉시상각하고 이자공제를 막거나 귀속이자까지 공제하고 경제적 감가상각을 따르면 법인세는 투자에 중립적이다":"가속상각·투자세액공제·법인세율 인하는 사용자비용을 낮추며, 즉시상각과 이자공제 규정이 갖춰지면 법인세가 투자에 중립적입니다.","가장 가난한 사람의 후생을 최대로 하는 최소극대화 원칙보다 동등한 자유의 원칙을 앞세웠다":"롤즈는 최소극대화 원칙보다 동등한 자유의 원칙이 우선한다고 보았습니다.","가치재 소비를 늘리려는 목적에 잘 맞고 규모의 경제가 있는 재화에 유리하지만 행정·운영비가 많이 든다":"현물보조는 가치재 소비를 늘리고 규모의 경제 재화에 유리하지만 행정과 운영에 비용이 많이 듭니다.","각 개인 한계대체율의 합이 한계변환율과 같은 ΣMRS = MRT, 곧 한계편익의 합이 한계비용과 같을 때다":"효율적 공급 조건은 개인들의 한계편익 합이 한계비용과 같아지는 것으로 이를 사무엘슨 조건이라 부릅니다.","각자가 공공재 비용의 부담비율을 제시하며 자발적으로 합의해 공급량을 정한다":"린달 모형은 각자 부담비율을 제시하며 자발적 합의로 공급량을 정하는 방식입니다.","각자가 낼 세금은 자기 표출 선호가 아니라 다른 사람들이 표출한 선호로 정해진다":"클라크세에서 내가 내는 세금은 나의 표출 선호가 아니라 다른 사람들이 밝힌 선호로 정해집니다.","감세액은 공제액 × 한계세율이라 누진세에서는 소득이 클수록 혜택이 크다":"소득공제의 감세액은 공제액에 한계세율을 곱한 값이라 누진세에서는 고소득자일수록 혜택이 큽니다.","같은 능력에 같은 세금이고 포괄적 소득세가 이를 높인다":"수평적 공평은 같은 능력에 같은 세금을 매기는 것이며 포괄적 소득세가 이를 높입니다.","같은 재화가 순수공공재라면 둘 다 1,000을 소비하므로 롤즈 후생은 낮은 쪽인 B의 효용 √1,000으로 정해진다":"순수공공재는 한 사람이 소비해도 다른 사람이 같은 양을 소비하므로 둘 다 1,000을 쓰고 후생은 B의 효용으로 정해집니다.","개별수요곡선을 수직으로 더해 구한다":"공공재의 시장수요는 사적재와 달리 개별수요곡선을 수직으로 더해 구합니다.","개인 선호에서 합리적이고 민주적인 집단 선택 규칙을 만들 수 없다는 뜻이다":"개인 선호를 모아 합리적이면서 민주적인 집단 선택 규칙을 만들 수 없다는 의미입니다.","거래 뒤 숨은 행동 때문에 생기며 CCTV 감시·공동보험·성과급처럼 행동을 살피거나 유인을 맞춰 줄인다":"도덕적 해이는 거래 후 숨은 행동 때문에 생기며, 감시·공동보험·성과급으로 행동을 점검하거나 유인을 일치시켜 줄입니다.","거래 전에 숨은 특성 때문에 생기며 졸업장·자격증 같은 신호발송, 품질보증, 책임보험·국민연금 강제가입으로 줄인다":"역선택은 거래 전에 상대의 숨은 특성 때문에 생기며, 신호발송·품질보증·강제가입 같은 방법으로 완화합니다.","결과보다 절차의 정의를 중시해 정당한 절차를 거치지 않았다면 균등분배도 정당하지 않다고 보았다":"노직은 결과가 아닌 절차의 정의를 중시해, 부정한 절차를 거치면 균등한 분배도 정당화되지 않는다고 보았습니다.","경계 위에서는 효율과 공평을 함께 높일 수 없다":"경계 위에서 한 사람을 더 낫게 하려면 다른 사람이 손해를 봐야 하므로 효율과 공평을 동시에 높이지 못합니다.","경기가 과열되면 특정기간 조세감면을 폐지하는 식으로 투자 유인을 줄인다":"과열기에는 특정 기간의 조세감면을 폐지해 투자 유인을 줄이는 방법을 씁니다.","고정 수수료에 대한 탄력성이 클수록 고정 수수료를 낮추고 사용 요금을 높이며 단일요금보다 효율적이다":"고정 수수료 수요가 탄력적일수록 고정 수수료는 낮추고 사용료는 높이는 방식이어서 단일요금보다 효율적입니다.","곡선이 교차해도 숫자 하나로 비교할 수 있지만 그 결과는 곡선의 모양 차이를 다 담지 못한다":"지니계수는 곡선이 교차하더라도 하나의 수치로 순위를 매길 수 있으나 곡선 모양 차이를 담지는 못합니다.","공공서비스에서 얻는 편익만큼 내라는 원칙으로 빅셀의 자발적 교환이론에 기초한다":"편익원칙은 공공서비스에서 얻는 편익만큼 부담하라는 원칙으로 빅셀의 자발적 교환이론이 그 근거입니다.","공공요금에도 (P − MC)/P = k/ε가 적용된다":"램지 가격은 공공요금에도 적용되어 가격과 한계비용의 차이 비율이 탄력성의 역수에 비례하도록 정합니다.","공공재가 정상재면 고소득자의 수요가 더 크고 중위투표자의 소득이 오르면 공공재 수요량도 늘어난다":"공공재가 정상재이면 소득이 높은 사람의 수요가 더 크고, 중위투표자의 소득이 올라도 공공재 수요가 늘어납니다.","공공재·외부성 같은 시장실패를 바로잡는 자원배분, 수평적·수직적 공평을 높이는 소득분배, 경제안정의 세 기능을 맡는다":"재정은 시장실패를 바로잡는 자원배분, 공평을 높이는 소득분배, 경제안정의 세 기능을 맡습니다.","공급비용이 같고 외부성과 규모의 경제가 없다면 지방공공재는 지역마다 선호에 맞춰 지방정부가 공급하는 것이 중앙정부의 획일적 공급보다 효율적이라고 했다":"비용이 같고 외부성·규모의 경제가 없다면 지방공공재는 지역 선호에 맞춰 지방정부가 공급할 때 더 효율적이라는 오우츠의 주장입니다.","공급이 Q = 50으로 고정되어 있으면 거래량이 변하지 않아 사중손실은 0이다":"공급량이 고정돼 있으면 과세해도 거래량이 변하지 않으므로 효율 손실인 사중손실이 생기지 않습니다.","공급이 고정된 토지에 과세하면 미래 세금의 현재가치만큼 땅값이 내려 과세 시점의 소유자가 모두 부담하고 이 자본화의 크기는 할인율에 반비례한다":"토지는 공급이 고정이라 세금이 가격에 반영되는 자본화로 땅값이 내려 소유자가 부담하며 할인율이 높을수록 자본화가 작아집니다.","공리주의 사회후생함수에서 실제 후생을 균등분배 때의 후생으로 나눈 값으로 1에 가까울수록 평등하다":"달튼의 평등지수는 공리주의 후생함수 아래 실제 후생과 균등분배 후생의 비율이며 1에 가까울수록 평등합니다.","공장 MB = 120 − Q, 피해 MD = Q/2이면 효율적 생산량은 Q = 80이다":"공장의 한계편익과 피해 곡선이 만나는 지점에서 효율적 생산량이 80으로 구해집니다.","공적연금은 강제가입으로 역선택을 막고 근시안적인 노후 준비를 보완한다":"강제가입은 역선택을 막고 근시안적인 노후 준비를 보완하는 장치입니다.","공평·확실(납부 시기·방법·금액을 알 수 있게)·편의·최소징세비이며 수입 극대화는 원칙이 아니다":"스미스의 조세 원칙은 공평·확실·편의·최소징세비이며 수입 극대화는 원칙에 포함되지 않습니다.","과세로 상대가격이 바뀌어 생기는 선택의 왜곡으로 소비자·생산자 후생 감소분에서 조세수입을 뺀 값이다":"초과부담은 과세로 상대가격이 바뀌어 선택이 왜곡되면서 생기는 후생 감소분에서 조세수입을 뺀 값입니다.","과세소득이 1,200만원까지 0%, 3,000만원까지 9%, 5,000만원까지 18%인 구조에서 과세소득 4,500만원이면 세액은 162만 + 270만 = 432만원이다":"구간별 세율을 적용해 과세소득 구간마다 세액을 더하면 총세액이 432만원으로 계산됩니다.","관료가 교부금을 받은 사실을 주민에게 알리지 않을 때 이런 착각이 생긴다":"관료가 교부금을 받은 사실을 주민에게 알리지 않으면 재정착각이 생길 수 있습니다.","관료는 공공서비스의 독점 공급자로서 예산 극대화를 추구해 총편익과 총비용이 같아지는 곳까지 생산한다":"니스카넨 모형에서 관료는 공공서비스의 독점 공급자로서 예산을 극대화해 총편익과 총비용이 같은 지점까지 생산합니다.","관료는 재량예산(실제 비용을 넘는 여유 예산)을 크게 하려 한다":"미그-빌레인저 모형에서 관료는 실제 비용을 넘는 여유 예산인 재량예산을 키우려 합니다.","관료의 예산극대화 성향도 지출 팽창의 원인이다":"관료가 예산을 극대화하려는 성향도 정부지출이 팽창하는 원인으로 꼽힙니다.","교부세와 보조금은 의존재원이라 재정자립도를 높이지 못하며 자율적 운영에는 교부세가 국고보조금보다 낫다":"교부세와 보조금은 재정자립도를 높이지 못하는 의존재원이고, 자율성 측면에서는 교부세가 더 낫습니다.","국고보조금은 용도가 정해진 조건부 보조금이고 조정교부금은 상위 자치단체가 하위 자치단체에 주는 돈이다":"용도가 정해진 보조금은 국고보조금이고, 상급 자치단체가 하급 자치단체에 나눠 주는 돈이 조정교부금입니다.","국방·외교는 중앙정부, 쓰레기 수거·거리청소처럼 조세부담과 편익의 연계가 강한 것은 지방정부 몫이다":"국방·외교는 중앙정부 몫이고, 쓰레기 수거·거리청소처럼 조세부담과 편익이 이어지는 일은 지방정부 몫입니다.","국세로 교육세·교통·에너지·환경세·농어촌특별세, 지방세로 지방교육세·지역자원시설세가 있고 재원을 안정적으로 확보하지만 재정 운영을 경직시킨다":"목적세는 특정 목적에 쓸 재원을 안정적으로 확보하지만 재정 운영을 경직시킨다는 약점이 있습니다.","국채로 세금을 줄여 주면 총수요가 늘어난다고 본다":"케인즈학파는 국채로 세금을 줄여 주면 가계 소득이 늘어 총수요가 늘어난다고 봅니다.","국채를 시중에서 소화하면 이자율이 올라 민간투자가 줄어든다":"국채를 시중에서 소화하면 이자율이 올라 민간투자가 줄어드는 구축효과가 나타납니다.","국채발행이 이자율을 올려 민간투자를 밀어내는 구축효과가 크다고 보며 그 효과는 경기침체기보다 호황기에 더 크다":"통화주의자는 국채발행이 이자율을 올려 민간투자를 밀어내는 구축효과가 크고, 그 효과는 호황기에 더 크다고 봅니다.","권리가 공장에 있으면 공장은 Q = 120까지 생산하려 하므로 피해자가 줄 최소 금액은 Q 80~120 구간 MB 면적 800이다":"권리가 공장에 있으면 공장은 120까지 생산하려 하므로 80에서 120 사이 한계편익 면적 800이 피해자가 줄 최소 금액입니다.","균형에서 각자의 부담비율은 자기 한계편익에 맞춰지고 부담비율의 합은 1이어서 사무엘슨 조건이 충족된다":"린달 균형에서는 부담비율이 각자 한계편익에 맞춰지고 합이 1이라 사무엘슨 조건이 충족됩니다.","균형에서는 기업마다 한계저감비용이 같아지고 처음 할당과 상관없이 총 저감비용이 최소가 된다":"거래가 끝난 균형에서는 기업마다 한계저감비용이 같아져 처음 할당이 어떻든 총 저감비용이 최소가 됩니다.","그 단계의 매출에만 세금을 면제하고 중간단계의 매입세액은 공제·환급하지 않는 부분면세다":"영세율과 달리 면세는 그 단계 매출만 면제하고 앞 단계에서 낸 매입세액은 환급해 주지 않는 부분면세입니다.","그래서 생산량은 효율적 수준보다 많지만 니스카넨 모형보다는 적다":"이 모형의 생산량은 효율적 수준보다 많지만 니스카넨 모형의 생산량보다는 적습니다.","그래서 시장에 맡기면 공공재가 과소공급된다":"그래서 시장에 맡기면 아무도 비용을 내지 않아 공공재가 사회적 최적보다 적게 공급됩니다.","그 생산수준에서 사회적 잉여는 0이 된다":"관료가 고른 생산수준에서는 총편익과 총비용이 같아져 사회적 잉여가 영이 됩니다.","근로의욕을 해치지 않지만 재분배 재원을 마련하기 어렵고 편익에 비례해 걷어도 무임승차가 생길 수 있다":"편익원칙의 장점은 근로의욕 저하가 없다는 것이고 단점은 재분배 재원 마련이 어렵고 무임승차 문제가 남는다는 것입니다.","기대값에서 위험프리미엄을 뺀 값이라 위험회피 성향이 클수록 작아진다":"확실성등가는 위험 회피 정도가 클수록 기대값에서 더 큰 위험프리미엄을 뺀 값이 됩니다.","기본요금으로 고정비 결손을 메우고 사용료를 한계비용에 맞춰 결손을 줄이면서 효율적 생산량에 이를 수 있다":"이부가격제는 기본요금으로 고정비 적자를 메우고 사용료를 한계비용에 맞춰 효율적 생산량을 달성하는 요금체계입니다.","기초생활필수품이 면세 대상이다":"기초생활필수품은 소득이 낮은 사람의 부담을 덜기 위해 면세 대상으로 둡니다.","납세자가 소유자이지만 물건을 기준으로 매기므로 대물세로 본다":"재산세는 납세자가 소유자이지만 물건을 기준으로 매기기 때문에 대물세로 분류합니다.","내부채무는 국민끼리 주고받는 것이라 미래세대의 부담이 아니고 외부채무는 미래세대에 부담이 넘어간다":"러너의 전통적 견해는 내부채무는 국민끼리 주고받는 것이라 미래세대의 부담이 아니고 외부채무는 부담이 넘어간다는 것입니다.","노동수요가 완전탄력적이거나 노동공급이 비탄력적이면 근로소득세는 근로자가 대부분 진다":"노동수요가 완전탄력적이거나 노동공급이 비탄력적이면 근로소득세 부담이 대부분 근로자에게 돌아갑니다.","노동집약적인 공공부문의 생산성이 민간보다 느리게 올라 공공서비스 생산비가 상대적으로 빠르게 오르는 현상이다":"공공부문은 노동집약적이라 생산성이 민간보다 느리게 올라 공공서비스 생산비가 상대적으로 빨리 오르는 보몰효과가 생깁니다.","누가 어떤 효용함수를 가졌는지 모르는 동등확률 아래서는 효용함수가 서로 달라도 균등분배가 최적이라고 보았다":"러너는 효용함수를 알 수 없는 동등확률 조건에서는 효용함수가 달라도 균등분배가 최적이라고 보았습니다.","누구의 효용도 줄이지 않고 한 사람 이상의 효용을 늘리는 변화":"파레토 개선은 아무도 손해 보지 않으면서 적어도 한 사람은 더 나아지는 자원배분의 변화입니다.","누진소득세와 실업보험 같은 자동안정장치는 경기에 따라 저절로 작동해 내부시차가 없으므로 시차 면에서는 재량적 재정정책보다 낫다":"누진소득세와 실업보험은 자동안정장치라 경기에 따라 자동으로 작동해 내부시차가 없어 재량적 정책보다 시차 면에서 유리합니다.","능력원칙과 편익원칙을 함께 구현할 수 있고 자산수익률이 노동수익률보다 높다면 자산과세를 강화할 때 소득분배가 개선된다":"재산세는 능력원칙과 편익원칙을 함께 구현할 수 있고, 자산수익률이 높다면 자산과세 강화가 분배 개선에 기여합니다.","능력이 클수록 더 내는 것이고 소득세 누진성 강화가 이를 높이지만 평균소득이 같아도 소득 변동이 큰 사업자는 누진세로 더 내게 되어 수평적 공평이 깨질 수 있다":"수직적 공평은 능력이 클수록 더 내는 것이지만, 평균소득이 같아도 소득 변동이 큰 사업자가 누진세로 더 내면 수평적 공평이 깨질 수 있습니다.","니스카넨은 대응책으로 민간이 생산하고 정부는 비용만 대는 방식을 제안했다":"니스카넨의 해법은 정부는 돈만 대고 민간이 생산하도록 하는 방식입니다.","다른 모든 대안과 1대1 다수결로 겨뤄 모두 이기는 대안이다":"꽁도세 승자는 다른 모든 대안과 일대일 다수결을 해서 전부 이기는 대안입니다.","다만 거둔 세금과 비용이 맞지 않아 정부의 균형예산은 늘 충족되지는 않는다":"다만 걷은 세금과 공급 비용이 일치하지 않아 정부의 균형예산이 항상 충족되지는 않는다는 한계가 있습니다.","다봉형 선호가 섞이면 생기며 중위투표자 정리도 성립하지 않는다":"다봉형 선호가 섞이면 투표의 역설이 생기며 이때는 중위투표자 정리도 성립하지 않습니다.","단기에는 세금과 같은 효과를 내지만 장기에는 진입을 불러 산업 생산량을 덜 줄인다":"보조금 효과는 기간에 따라 달라서 시간이 지나면 업계 진입이 늘어 산업 전체의 산출 감소가 작아집니다.","단일세율이면 소득 대비 부담이 저소득층에 무거운 역진적 세금이다":"단일세율의 부가가치세는 소득 대비 부담이 저소득층에 더 무거운 역진적 세금입니다.","당사자가 많거나 피해 규모 정보가 비대칭이면 거래비용이 커져 현실 적용이 어렵고 정부 개입이 정당화된다":"인원수를 곱해 집단 수요로 바꾼 뒤, 집단들의 수요를 같은 수량에서 더해 전체 수요를 만듭니다.","대가를 내지 않은 사람도 소비에서 막을 수 없는 성질이다":"비배제성은 값을 안 낸 사람도 소비에서 막지 못하는 성질입니다.","대각선과 로렌츠곡선 사이 면적을 대각선 아래 삼각형 면적으로 나눈 값으로 0(완전 평등)에서 1 사이다":"지니계수는 대각선과 로렌츠곡선 사이 면적을 삼각형 면적으로 나눈 값이며 영이면 완전 평등입니다.","대규모 공사로 건축자재 값이 올라 다른 업자가 손해를 보는 것처럼 상대가격 변동을 거쳐 전달된다":"금전적 외부성은 건축자재 값이 오르듯이 상대가격 변화를 통해서만 다른 사람에게 전달됩니다.","대안 4개에 1순위 3점부터 4순위 0점을 주고 A형 4명·B형 3명·C형 2명의 순위를 합산하면 b가 19점으로 뽑힌다":"네 대안에 순위별 점수를 주고 유형별 인원을 곱해 합하면 b가 19점으로 가장 높아 선택됩니다.","대응보조금은 공공재의 상대가격을 낮춰 대체효과까지 일으키므로 공공재 소비를 더 크게 늘리지만 선택을 왜곡하고 사적재 소비는 늘 수도 줄 수도 있다":"대응보조금은 공공재 상대가격을 낮춰 소비를 가장 크게 늘리지만 선택을 왜곡하고 사적재 소비는 늘거나 줄 수 있습니다.","대체재인 X재에 이미 세금이 있으면 Y재에 새로 과세해 경제 전체의 초과부담이 오히려 줄 수 있다":"차선의 이론은 이미 세금이 붙은 대체재가 있으면 다른 재화에 새로 과세하는 것이 오히려 경제 전체의 초과부담을 줄일 수 있다는 것입니다.","대체효과로 노동공급을 줄이고 여가가 정상재면 소득효과로 늘려 총효과가 불분명하다":"비례소득세는 대체효과로 노동공급을 줄이고 여가가 정상재이면 소득효과로 늘려서 전체 효과를 알 수 없습니다.","대체효과 없이 소득효과만 있어 여가가 정상재면 노동공급이 늘고 열등재면 준다":"정액세는 대체효과 없이 소득효과만 있으므로 여가가 정상재이면 노동공급이 늘고 열등재이면 줄어듭니다.","대체효과와 소득효과를 함께 일으켜 해당 재화 소비를 가장 크게 늘리지만 비효율을 낳는다":"가격보조는 소비자가 지불하는 가격을 낮춰 해당 재화 소비를 가장 크게 늘리나 비효율이 큽니다.","독점 상품을 사서 그만큼 생산이 늘면 한계비용으로, 생산이 그대로면 시장가격으로 평가한다":"시장이 완전하지 못하면 시장가격이 사회적 가치와 달라 사회적 기회비용을 구하는 잠재가격이 필요합니다.","독점에는 공급곡선이 없어 공급탄력성으로 귀착을 설명할 수 없고 세금 일부만 소비자에게 넘어간다":"독점에는 공급곡선이 없어서 탄력성 논리가 통하지 않고 세금이 일부만 소비자에게 전가됩니다.","두 사람이 공공재 비용 분담에 찬반을 고르는 게임에서 반대가 우월전략이면 서로 반대하는 것이 유일한 내쉬균형이 된다":"공공재 비용 분담에서 반대가 우월전략이면 둘 다 반대하는 것이 유일한 내쉬균형이 됩니다.","두 산업의 한계기술대체율(MRTS)이 같을 때 이루어진다":"생산의 효율은 두 산업이 생산요소를 대체하는 비율이 같아져 요소를 옮겨도 이득이 없을 때 달성됩니다.","두 소비자의 한계대체율(MRS)이 같을 때 이루어진다":"교환의 효율은 두 소비자가 재화 사이에서 느끼는 주관적 교환비율이 같아질 때 달성됩니다.","두 재화가 완전보완재면 한 재화에 과세해도 보상수요량이 변하지 않아 초과부담이 0이다":"보완관계가 완전한 두 재화는 한쪽에 과세해도 소비 비율이 달라지지 않아 초과부담이 영이 됩니다.","매년 모든 사업을 처음부터 다시 평가해 점증주의를 벗어나지만 시간과 비용이 많이 든다":"영기준 예산은 매년 모든 사업을 백지에서 평가해 점증주의를 극복하나 시간과 비용이 많이 듭니다.","매출에 0% 세율을 적용하고 앞 단계에서 낸 매입세액을 환급해 주므로 부가가치세 부담이 완전히 사라지는 완전면세이며 수출품에 쓴다":"영세율은 매출에 0% 세율을 적용하고 매입세액도 환급해 부가가치세 부담을 완전히 없애는 완전면세로 수출품에 씁니다.","머스그레이브의 재정 3기능 가운데 소득분배와 경제안정은 중앙정부가, 자원배분 일부는 지방정부가 맡는 것이 바람직하다":"소득분배와 경제안정은 중앙정부, 자원배분의 일부는 지방정부가 맡는 편이 좋다는 것이 머스그레이브 구분입니다.","명목소득과 물가가 함께 오르면 비례세의 실질세액은 그대로지만 누진세는 높은 구간으로 밀려 실질 부담이 커진다":"물가와 명목소득이 함께 오르면 누진세에서는 구간 상승으로 실질 세부담이 늘어나고 비례세는 영향이 없습니다.","명목이자율 5%, 세율 20%, 물가상승률 3%이면 세후 실질수익률은 5 × 0.8 − 3 = 1%다":"세후 실질수익률은 명목이자율에 세후 비율을 곱하고 물가상승률을 빼 구합니다.","모두 같은 양을 소비하지만 각자 다른 가격을 치르고 그 가격의 합이 한계비용과 같다":"공공재는 모두가 같은 양을 소비하되 지불가격은 사람마다 다르고 그 합이 한계비용과 같아집니다.","모두 파레토 효율적이며 그런 점은 무수히 많다":"효용가능경계 위의 점은 모두 파레토 효율적이며, 그런 점이 무수히 많습니다.","모든 투표자의 선호가 단봉형이면 단순다수결의 결과는 선호가 한가운데 있는 중위투표자가 원하는 안이 된다":"선호가 단봉형이라면 다수결은 한가운데 투표자의 선호를 따라가므로 중위투표자의 안이 선택됩니다.","모딜리아니-밀러 제1명제는 법인세·파산비용·정보비대칭이 없으면 자본구조가 기업가치와 무관하다는 것이다":"법인세와 파산비용, 정보 비대칭이 없다면 기업가치는 자금조달 방식인 자본구조와 무관하다는 모딜리아니-밀러 명제입니다.","무조건부(비대응) 보조금은 소득효과만 일으켜 공공재와 사적재 소비를 함께 늘리고 일부는 주민 조세부담을 덜어 주므로 같은 금액이면 후생 면에서 가장 낫다":"무조건부 보조금은 소득효과만 내서 공공재와 사적재 소비를 함께 늘리며 같은 금액이면 주민 후생이 가장 높습니다.","무형 편익을 돈으로 재기 힘들면 같은 목표를 가장 싸게 이루는 대안을 고르는 비용효과분석을 쓴다":"무형 편익을 돈으로 환산하기 어려우면 같은 목표를 가장 싸게 달성하는 대안을 고르는 비용효과분석을 씁니다.","미국은 연방 부가가치세가 없고 주 정부가 소매판매세를 걷는다":"미국은 연방 부가가치세가 없고 주 정부가 소매판매세를 걷는다는 점이 우리나라와 다릅니다.","민간이 가진 국채 잔액이 늘어 부유해졌다고 느껴 소비가 느는 현상을 러너효과라 한다":"국채 보유 잔액이 늘어 부유해졌다고 느끼면 소비가 늘어나는 현상을 러너효과라 합니다.","반대로 정부를 개인의 목적을 이루기 위한 도구로 본다":"기계적 국가관은 앞의 입장과 반대로 정부를 개인의 목적 달성을 위한 도구로 봅니다.","반드시 꽁도세 승자이지만 과반이 안 되는 최다득표자는 아닐 수 있다":"과반수 득표자는 반드시 꽁도세 승자이지만 과반이 못 되는 최다득표자는 꽁도세 승자가 아닐 수 있습니다.","배제가 가능하고 이용자가 늘면 혼잡이 생기는 재화로 시장에서도 효율적으로 공급될 수 있다":"클럽재는 이용자를 가릴 수 있으나 이용자가 늘면 혼잡이 생기는 재화이며 시장에서도 효율적 공급이 가능합니다.","배제가 어렵지만 경합적이라 남용된다":"공유자원은 이용자를 막기 어렵지만 서로 경합해서 남용되기 쉬운 재화입니다.","법인세 등은 납세의무자와 담세자가 같고 누진과세가 가능해 소득분배 개선에 유리하다":"직접세는 납세의무자와 담세자가 같고 누진과세가 가능해 소득분배를 개선하는 데 유리합니다.","법인세 부담이 상품가격 인상으로 소비자에게 넘어가면 전방전가다":"기업이 법인세 부담을 가격에 얹어 소비자에게 넘기는 현상을 전방전가라 합니다.","법인세와 소득세의 완전통합은 조합방식·자본이득방식, 부분통합은 배당세액공제·차등세율제도이며 대부분의 나라는 부분통합을 쓴다":"통합 방식으로는 조합·자본이득방식(완전통합), 배당세액공제·차등세율(부분통합)이 있으며 부분통합이 보편적입니다.","법적 귀착은 법이 정한 납세자, 경제적 귀착은 실제 부담자이며 둘은 다를 수 있다":"법적 귀착은 법이 정한 납세자에게 생기고 경제적 귀착은 실제 부담하는 사람에게 생겨 둘이 다를 수 있습니다.","병원 방문 수요가 P = 400 − Q이고 비용 100에 본인부담 20이면 방문이 300에서 380으로 늘어 도덕적 해이의 후생비용은 ½ × 80 × 80 = 3,200이다":"본인부담을 두면 병원 방문이 300에서 380으로 늘어나는 구조에서 도덕적 해이로 생기는 후생비용이 3,200입니다.","보다투표는 순위에 점수를 매겨 합한다":"보다투표는 선호 순위마다 점수를 매겨 합산하는 방식입니다.","보조금 S = m − tE(m은 기초수당, t는 한계세율, E는 번 소득)이므로 E = m/t에서 보조가 끊긴다":"부의 소득세는 소득이 늘수록 보조금이 줄어들어 일정 소득 수준에서 끊기는 구조입니다.","보조금이 들어와도 지방세가 줄지 않고 지방정부 지출이 같은 금액의 주민소득 증가 때보다 더 크게 느는 현상이다":"보조금이 들어와도 지방세를 줄이지 않고 지출이 소득 증가보다 더 크게 느는 현상이 끈끈이 효과입니다.","부가가치세 등은 가격에 숨어 조세저항과 징세비용이 작지만 역진적이다":"간접세는 가격에 숨어 조세저항과 징세비용이 작지만 소득 대비 부담이 저소득층에 무거워 역진적입니다.","부가가치에만 과세하므로 기업을 수직적으로 합쳐도 세부담이 같아 수직적 통합을 부추기지 않는다":"기업 규모를 키워 단계를 줄여도 부가가치 합이 같아 세금이 같으므로 수직적 통합을 유도하지 않습니다.","부담능력이 다르면 세금도 달라야 한다는 원칙으로 밀의 동등희생 원칙에 근거한다":"능력이 다르면 세금도 달라야 한다는 능력원칙은 밀의 동등희생 이론에서 나왔습니다.","부동산 경기는 취득세 등을 거쳐 지방재정의 규모와 안정성을 흔든다":"부동산 경기가 취득세를 통해 지방재정의 규모와 안정성에 영향을 줍니다.","부동산 공급탄력성이 0이면 과세해도 초과부담이 없고 보유세를 올리면 자본화로 부동산 가격이 내린다":"부동산 공급탄력성이 영이면 과세해도 초과부담이 없고, 보유세를 올리면 세금이 땅값에 자본화되어 가격이 내립니다.","분배만 바꿀 뿐 자원배분의 효율성에는 영향이 없다":"금전적 외부성은 소득을 이전시킬 뿐 자원배분의 효율성은 바꾸지 않습니다.","분배 문제를 효율과 떼어 다룰 수 있다는 뜻일 뿐 효율이 공평을 보장한다는 뜻은 아니다":"분배를 효율과 분리해서 다룰 수 있다는 의미일 뿐, 효율이 곧 공평을 보장한다는 의미는 아닙니다.","불완전경쟁·공공재·외부성·정보의 비대칭·불완비 시장(보험시장 등)이 시장실패를 낳는다":"시장실패는 독점 같은 불완전경쟁, 공공재, 외부성, 정보 비대칭, 불완비 시장에서 생깁니다.","불평등 혐오도가 클수록·세수 목표가 클수록 최적 한계세율이 높고 노동공급이 탄력적일수록 낮다":"스턴의 선형소득세 분석에서는 불평등 혐오도와 세수 목표가 클수록 최적 한계세율이 높고 노동공급이 탄력적일수록 낮습니다.","비례적 소득세로 비용을 나누면 다수결 결과가 최적보다 과대 공급될 수 있다":"비례적 소득세로 비용을 나누면 다수결로 정해진 공급이 최적보다 과다해질 수 있습니다.","비배제성 때문에 각자는 선호를 숨기고 남이 낸 비용으로 소비하려 한다":"비배제성 때문에 사람들은 자기 선호를 숨기고 남이 낸 비용에 편승하려 해서 무임승차가 생깁니다.","비용 1,000을 들여 A는 2년 뒤 1,210, B는 1년 뒤 1,150을 얻는다면 IRR은 A 10%, B 15%다":"비용 1,000으로 2년 뒤 1,210을 얻는 A는 수익률이 10%이고 1년 뒤 1,150을 얻는 B는 15%입니다.","비용편익분석은 공공부문뿐 아니라 민간 투자계획의 타당성 판정에도 쓰인다":"비용편익분석은 공공 사업뿐 아니라 민간의 투자계획 타당성을 판정하는 데도 쓰입니다.","사람들이 선호를 숨기면 무너지므로 소수일 때만 현실성이 있다":"이 모형은 선호를 숨기는 순간 무너지므로 구성원이 적을 때만 현실성이 있습니다.","사업으로 시장가격이 내리면 늘어난 소비자잉여를 편익에 넣는다":"사업 때문에 시장가격이 내리면 늘어난 소비자잉여를 편익으로 계산합니다.","사업으로 이득을 보는 사람이 손해 보는 사람을 보상하고도 남으면 채택한다는 잠재적 파레토 개선 기준이다":"칼도-힉스 기준은 이득을 본 사람이 손해 본 사람을 보상하고도 남으면 사업을 채택하는 잠재적 파레토 개선 기준입니다.","사업의 산출을 중심으로 편성한다":"성과주의 예산제도는 사업의 산출을 중심으로 편성합니다.","사업 자금의 기간당 기회비용에 맞춘다":"할인율은 사업 자금의 기간당 기회비용에 맞춰 선택합니다.","사적재이지만 정부가 소비를 장려하려고 공급하거나 지원하는 재화이고 상수도·우편·철도도 사적재 성격이 강하다":"가치재는 사적재이면서도 정부가 소비를 권장해 공급하거나 지원하는 재화이며 상수도·우편·철도도 사적재 성격이 강합니다.","사회를 하나의 유기체로 보고 개인은 그 한 부분이며 정부는 심장부라고 본다":"유기체적 국가관은 사회를 하나의 생명체로 보아 개인을 그 일부, 정부를 심장부로 바라보는 입장입니다.","사회적 최적보다 과다 생산된다":"해로운 외부성이 있는 재화는 사회적 최적 수준보다 과다하게 생산됩니다.","사회적 한계편익과 사회적 한계비용이 같을 때다":"외부성이 있을 때 효율적 배분은 사회적 한계편익과 사회적 한계비용이 같아지는 지점입니다.","산재보험료는 사용자가 전액 내고 기초연금은 조세로 충당한다":"산재보험료는 사용자만 내고 기초연금은 세금으로 마련합니다.","산출물 구성까지 효율적이려면 MRS = MRT여야 한다":"교환과 생산뿐 아니라 어떤 재화를 얼마나 만들지까지 효율적이려면 소비 측 교환비율이 생산 측 변환비율과 같아야 합니다.","상대가격 변화로 소득이 옮겨 갈 뿐이라 편익에 넣지 않는다":"금전적 편익은 상대가격 변화로 소득이 이전될 뿐 사회 전체의 후생이 늘지 않아 편익에 넣지 않습니다.","상대가격을 바꾸지 않아 대체효과가 없고 같은 돈이면 소비자 효용이 현물보조보다 같거나 높다":"현금보조는 가격 신호를 바꾸지 않아 대체효과가 없으므로 같은 돈이면 현물보조보다 소비자 만족이 같거나 높습니다.","상위 20% 소득점유율을 하위 20% 점유율로 나눈 값이라 완전 균등이면 1이고 클수록 불평등하다":"상위 20% 소득점유율을 하위 20% 점유율로 나눈 지표이며, 값이 클수록 불평등을 뜻하고 균등하면 1입니다.","생산량이 같다면 종가세의 세수가 종량세보다 많고 이윤세는 이윤극대화 생산량을 바꾸지 않는다":"생산량이 같을 때는 가격에 비례하는 종가세가 단위당 종량세보다 세수가 많고, 이윤세는 생산량을 바꾸지 못합니다.","생산·유통 각 단계에서 새로 붙은 부가가치에만 과세하는 일반소비세로 1954년 프랑스에서 처음 등장했다":"부가가치세는 각 단계에서 새로 붙은 부가가치에만 과세하는 일반소비세이며 1954년 프랑스에서 처음 도입되었습니다.","생산이 그대로면 소비자가격으로, 생산이 늘면 생산자가격으로 평가한다":"물품세가 붙은 투입물은 생산이 그대로이면 소비자가격으로, 생산이 늘면 생산자가격으로 평가합니다.","생산 효율만 보장하므로 MRS가 MRT와 다르면 생산 구성을 바꿔 모두를 낫게 할 수 있다":"생산가능곡선 위의 점은 생산만 효율적이라, 소비자의 교환비율이 변환비율과 다르면 생산 구성을 조정해 모두를 더 낫게 할 여지가 있습니다.","선택 대상이 제한된 경우 이런 서열을 만들 수 있다고 보았다":"센은 선택 대상을 제한하면 이런 사회적 서열을 만들 수 있다고 보았습니다.","선호와 생산이 볼록하면 초기부존을 재분배해 어떤 파레토 효율적 배분도 경쟁균형으로 이룰 수 있다는 것이다":"선호와 생산이 볼록하다면 초기부존을 다시 나누는 것만으로 원하는 효율적 배분을 경쟁시장에서 달성할 수 있습니다.","세법상 감면으로 걷지 않게 된 세수로 특별감가상각·투자세액공제·기부금 소득공제가 예이고 보조금 지급은 재정지출이다":"세법상 감면으로 걷히지 않게 된 세수가 조세지출이며 투자세액공제와 기부금 소득공제가 예이고 보조금은 재정지출입니다.","세수 1원을 더 걷을 때의 한계초과부담이 모든 재화에서 같도록 세율을 정하면 보상수요량의 감소율이 모든 재화에서 같아진다":"램지 규칙은 한계초과부담이 모든 재화에서 같도록 세율을 정하는 것이며, 그러면 보상수요량이 같은 비율로 줄어듭니다.","세수가 같다면 한 재화에 몰아 걷기보다 두 재화에 나눠 걷을 때 초과부담이 작다":"같은 세수라면 한 재화에 몰아 걷기보다 두 재화에 나누어 걷는 쪽이 초과부담이 작습니다.","세수가 일정할 때 효용을 최대로 하려면 과세구간마다 한계세수당 한계효용(MU/MR)이 같아야 한다":"세수가 고정된 상태에서 효용을 극대화하려면 모든 과세구간의 한계효용 대 한계세수 비율이 같아야 합니다.","세율은 적정하게 두고 행정비용이 덜 드는 벌금률 인상으로 탈세를 막는 쪽이 낫다고 본다":"세율을 그대로 두고 행정비용이 덜 드는 벌금 인상으로 억제하는 것이 낫다는 정책 처방입니다.","세율이 2배면 초과부담은 4배로 커지고 세수는 늘지 않을 수도 있으며 대체재가 적어 수요가 비탄력적인 재화일수록 초과부담이 작다":"세율이 두 배가 되면 초과부담은 네 배가 되고 세수는 늘지 않을 수 있으며 수요가 비탄력적인 재화는 초과부담이 작습니다.","세율이 오르면 소득효과는 탈세를 줄이고 대체효과는 늘려서 방향이 불분명하지만 감사확률과 벌금률을 높이면 탈루소득이 준다":"세율이 오르면 소득효과와 대체효과가 상반되어 탈세 방향이 불분명하고, 적발 확률과 벌금이 오르면 탈루가 줄어듭니다.","세후 이자율이 내리면 현재소비의 상대가격이 내린다":"이자소득세가 부과되면 세후 이자율이 내려가 현재소비의 상대가격이 내려갑니다.","소득세·일반소비세나 모든 재화에 같은 세율을 매기면 재화 사이 상대가격이 그대로라 재화 선택에 중립적이고 특정 재화에만 물품세를 매기면 선택이 왜곡된다":"모든 재화에 동일한 세율을 매기면 상대가격이 유지되어 중립적이지만, 일부 재화에만 매기면 소비 선택이 왜곡됩니다.","소득이 같은 가족에 같은 세금을 매겨 수평적 공평을 지키지만 결혼으로 세부담이 달라져 결혼중립성이 깨지고 개인단위 과세는 그 반대다":"부부 합산과세는 같은 소득의 가족에 같은 세금을 내게 하나 결혼에 따라 세부담이 달라지는 결혼중립성 문제가 있습니다.","소득 합만 보는 공리주의 함수에서는 균등분배대등소득이 평균소득과 같아 지수가 0이다":"공리주의 후생함수는 소득 합만 보므로 균등분배대등소득이 평균소득과 같아 지수가 영이 됩니다.","소득효과가 대체효과보다 크면 노동공급곡선이 후방굴절하고 여가가 열등재면 두 효과 모두 노동공급을 줄인다":"소득효과가 크면 임금이 올라도 노동이 줄어드는 후방굴절이 생기고, 여가가 열등재이면 두 효과가 노동을 함께 줄입니다.","소득효과가 아니라 대체효과 때문에 생기므로 보상수요곡선으로 재야 한다":"초과부담은 대체효과 때문에 생기므로 소득효과를 뺀 보상수요곡선으로 측정해야 합니다.","소득효과가 없어야 하고 협상 이득이 협상 비용보다 커야 한다":"코즈 정리가 성립하려면 소득효과가 없어야 하고 협상으로 얻는 이득이 협상 비용보다 커야 합니다.","소득효과와 대체효과가 상쇄되어 수요량이 그대로여도 초과부담은 생긴다":"수요량이 그대로여도 소득효과와 대체효과가 상쇄된 결과일 뿐 초과부담은 사라지지 않습니다.","소비자 부담 : 생산자 부담 = 공급탄력성 : 수요탄력성이고 수요가 완전비탄력적이면 소비자가 전부 낸다":"부담 비율은 공급탄력성 대 수요탄력성의 비이고, 수요가 완전비탄력적이면 소비자가 세금 전부를 부담합니다.","소비자에게 단위당 12를 과세하면 생산자 수취가격이 32가 되어 생산자가 8, 소비자가 4를 부담한다":"단위당 12를 부과하면 생산자 수취가격이 32로 내려 생산자가 8을 부담하고 소비자는 4를 부담합니다.","소수에게 비용을 떠넘기는 다수결과 투표거래(로그롤링)는 과다공급을 낳고 다운즈의 합리적 무지와 갤브레이스의 의존효과는 과소공급을 설명한다":"소수에게 비용을 떠넘기는 다수결과 로그롤링은 과다공급을, 합리적 무지와 의존효과는 과소공급을 설명합니다.","소유권이 분명하지 않은 자원은 각자 아껴 쓸 유인이 없어 남용되고 빨리 고갈된다":"소유권이 불분명한 자원은 아껴 쓸 유인이 없어 남용되고 금방 고갈되는데 이것이 공유지의 비극입니다.","손실상계가 없으면 대체효과는 위험자산을 줄이고 소득효과가 대체효과보다 클 때만 비중이 늘어난다":"손실상계가 없을 때 대체효과는 위험자산을 줄이고 소득효과가 더 클 때만 위험자산 비중이 늘어납니다.","손실이 없으나 과소생산이 남고 비용절감 유인을 주지 못한다":"평균비용 가격은 손실이 안 나는 대신 생산이 과소하고 기업이 비용을 줄일 유인도 주지 못합니다.","수요 P = 16 − Q/2, MC = 12이면 효율적 규모는 8이지만 관료는 16Q − Q²/4 = 12Q에서 Q = 16을 고른다":"효율적 규모는 한계편익과 한계비용이 같은 8이지만 관료는 총편익이 총비용과 같은 16까지 생산합니다.","수요가 P_1 = 50 − Q, P_2 = 40 − (2/3)Q이고 단위비용 60이면 Q = 18에서 부담은 32와 28이다":"두 사람의 수직합이 단위비용 60과 같아지는 곳에서 공급량이 18이고 각자의 부담은 32와 28입니다.","수요의 가격탄력성이 작을수록 가격을 한계비용보다 높게 매기므로 필수품에서 분배 문제가 생긴다":"램지 가격은 수요의 가격탄력성이 작은 재화일수록 가격을 한계비용보다 높게 정해 필수품에 부담이 몰리는 분배 문제가 생깁니다.","수요자와 공급자 중 누구에게 부과하든 결과가 같고 상대적으로 비탄력적인 쪽이 더 많이 부담한다":"물품세는 누구에게 부과해도 결과가 같고 상대적으로 비탄력적인 쪽이 더 많이 부담합니다.","순수공공재는 둘을 모두 갖추며 현실의 공공재는 대부분 일부만 갖춘 비순수공공재다":"순수공공재는 비경합성과 비배제성을 모두 갖추고, 현실의 대부분은 한쪽만 갖춘 비순수공공재입니다.","순편익이 음수(비용)라면 위험할인율만큼 비용을 더 크게 잡는다":"순편익이 음수인 비용이면 위험할인율만큼 비용을 더 크게 잡아 위험을 반영합니다.","순현재가치(NPV)가 0보다 크거나 편익·비용비율(B/C)이 1보다 크거나 내부수익률(IRR)이 할인율보다 크면 사업을 채택한다":"순현재가치·비용편익비·내부수익률 세 지표 중 어느 하나의 기준을 넘으면 사업을 채택할 수 있습니다.","시설이 남는 비수기에는 한계비용만 받고 용량이 차서 초과수요가 있으면 한계비용에 경제적 지대를 더해 받는 것이 효율적이다":"용량에 여유가 있는 비수기와 꽉 찬 성수기의 요금을 다르게 정하는 것이 효율적이라는 설명입니다.","시장 밖에서 직접 효용이나 생산에 영향을 주어 비효율을 낳는다":"기술적 외부성은 시장을 거치지 않고 효용이나 생산에 직접 영향을 주어 비효율을 낳는 외부성입니다.","시장실패는 정부개입의 필요조건일 뿐 충분조건이 아니다":"시장이 실패했다고 정부가 반드시 개입해야 하는 것은 아니어서, 시장실패는 개입의 필요조건일 뿐 충분조건이 아닙니다.","시장에서 파악되지 않는 무형의 편익·비용과 외부적 편익도 함께 고려한다":"무형의 효과와 외부적 편익은 시장가격으로는 안 잡히므로 따로 고려해야 합니다.","시장이 불완전하거나 왜곡되면 시장가격 대신 사회적 기회비용인 잠재가격을 쓴다":"독점기업이 시장가격보다 낮은 한계비용으로 공급한다는 점에서 잠재가격이 필요해집니다.","시장이자율이 사회적 할인율보다 높은데 시장이자율을 쓰면 공공사업의 경제성이 낮게 평가된다":"시장이자율이 사회적 할인율을 웃도는데도 이를 쓰면 공공사업이 실제보다 비경제적인 것처럼 평가됩니다.","실질소득이 줄어 소득효과로 정상재 소비는 줄고 열등재 소비는 는다":"물품세로 실질소득이 낮아지면 정상재는 덜, 열등재는 더 소비하게 됩니다.","애로는 완벽한 조건부거래시장이 있으면 불확실성이 있어도 시장실패가 없음을 보였다":"애로의 결론은 완벽한 조건부거래시장이 있으면 불확실성 아래에서도 시장실패가 없다는 것입니다.","양당의 공약이 중위투표자 쪽으로 비슷해지는 현상을 설명하지만 그 균형이 파레토 효율을 보장하지는 않는다":"두 정당의 공약이 중위투표자 쪽으로 가까워지는 현상은 설명하지만, 그 결과가 파레토 효율을 보장하지는 않습니다.","양도소득세는 팔기를 미루게 하는 동결효과로 거래를 위축시킨다":"양도소득세가 있으면 팔기를 미루는 동결효과가 나타나 부동산 거래가 위축됩니다.","여러 사업의 우선순위는 NPV 크기로 정하며 IRR과 NPV의 결론이 늘 같지는 않다":"사업 우선순위는 순현재가치의 크기로 정하며, 내부수익률과 순현재가치의 결론이 항상 같은 것은 아닙니다.","연구개발, 양봉과 과수원이 있으면 과소 생산된다":"연구개발이나 양봉처럼 이로운 외부성이 있는 활동은 최적보다 과소하게 이루어집니다.","연금 기대는 자산대체효과로 민간저축을 줄이고 은퇴효과·상속효과·인식효과는 저축을 늘린다":"공적연금은 연금 기대 때문에 민간저축을 줄이는 자산대체효과를 낳고, 은퇴효과·상속효과·인식효과는 저축을 늘립니다.","완비성·이행성, 파레토 원칙, 무관한 대안의 독립성, 비독재성을 모두 만족하는 사회적 선호체계는 없다":"애로의 정리는 네 가지 합리적 조건을 한꺼번에 충족하는 사회적 선호 집계 방식이 존재하지 않는다는 결론입니다.","완전 개방경제에서 자본에 과세하면 자본은 빠져나갈 수 있어 이동하지 못하는 자본 사용자 쪽이 부담한다":"자본은 세금을 피해 해외로 이동할 수 있어서 이동이 어려운 자본 사용 측이 대신 부담합니다.","완전손실상계가 있으면 정부가 수익과 손실을 함께 나눠 지므로 위험자산의 비중이 커진다(도마-머스그레이브)":"손실을 정부가 분담해 주는 완전손실상계에서는 위험자산 비중이 커진다는 것이 도마-머스그레이브의 결론입니다.","외부성을 일으키는 쪽에 최적 생산량에서의 한계피해(MD)만큼 단위당 세금을 매겨 외부비용을 사적 비용에 반영하며 오염세를 내는 기업은 배출을 줄일수록 세금이 줄어 감축기술 개발 유인을 갖는다":"피구세는 외부성을 일으킨 쪽에 최적 생산량에서의 한계피해만큼 단위당 세금을 물려 외부비용을 사적 비용에 반영하는 정책입니다.","외부성이 없고 시장이 완비된 완전경쟁의 일반균형이 파레토 효율적이라는 것으로 보이지 않는 손을 뜻한다":"완전경쟁 일반균형은 외부성이 없고 시장이 완비되면 파레토 효율적이라는 정리로, 보이지 않는 손의 현대적 표현입니다.","용도가 정해지지 않은 무조건부 교부금으로 보통교부세·특별교부세·부동산교부세·소방안전교부세가 있다":"용도 지정 없이 주는 무조건부 교부금인 지방교부세에는 보통·특별·부동산·소방안전교부세가 있습니다.","우리나라 개인소득세는 개인단위로 과세한다":"우리나라 개인소득세는 개인을 단위로 과세한다는 점이 합산과세와 다릅니다.","우리나라는 매출세액에서 매입세액을 빼는 매입세액공제방식을 써서 거래 상대방끼리 세금계산서로 서로 확인되어 탈세를 막는다":"우리나라는 매출세액에서 매입세액을 빼는 방식이라 거래 상대방이 세금계산서로 서로 확인해 탈세가 어렵습니다.","우리나라는 비슷한 업무를 묶어 편성하는 프로그램 예산제도를 2007년부터 도입했다":"프로그램 예산제도는 비슷한 업무끼리 묶어 편성하는 방식으로 우리나라가 2007년에 도입했습니다.","우리나라는 소비형을 채택하고 있다":"우리나라 부가가치세는 세 유형 중 소비형을 채택하고 있습니다.","우리나라는 취득할 때 지방세인 취득세를, 보유할 때 재산세와 종합부동산세를, 양도할 때 국세인 양도소득세를 걷는다":"부동산은 취득할 때 취득세, 보유할 때 재산세와 종합부동산세, 양도할 때 양도소득세가 붙습니다.","우리나라 사회보험은 국민연금·건강보험·고용보험·산재보험·노인장기요양보험 5가지로 보험료가 주 재원이고 공공부조(국민기초생활보장 등)는 세금으로 기여와 관계없이 대상자를 지원한다":"사회보험은 국민연금·건강보험·고용보험·산재보험·노인장기요양보험이고 보험료가 주 재원이며, 공공부조는 세금으로 지원합니다.","우리나라 지방세 규모는 국세보다 작고 국세든 지방세든 세목은 법률에 근거해야 신설할 수 있다":"우리나라 지방세 규모는 국세보다 작고 세목 신설은 법률에 근거해야 합니다.","위험부담의 소득탄력성이 양(+)이면 손실상계가 없을 때 두 효과 모두 위험자산 투자를 줄인다":"위험부담의 소득탄력성이 양인데 손실상계가 없다면 대체효과와 소득효과가 모두 위험투자를 줄입니다.","이때는 대진 순서에 따라 승자가 달라지고 의사진행 조작이 가능하다":"투표의 역설이 있으면 안건을 붙이는 순서에 따라 승자가 달라져 의사진행을 조작할 수 있습니다.","이를 중위투표자의 선택과 묶어 중위투표자의 공공서비스 수요 소득탄력성이 충분히 크면 정부지출 비중이 커진다고 했다":"브라운-잭슨은 바그너 법칙을 중위투표자와 연결해 중위투표자의 공공서비스 수요 소득탄력성이 충분히 크면 정부지출 비중이 커진다고 했습니다.","이 비율이 낮은 구간은 세율을 올리고 높은 구간은 세율을 내린다":"한계세수당 한계효용이 낮은 구간은 세율을 올리고 높은 구간은 세율을 내려 균형을 맞춥니다.","이자소득세 없이 근로소득세만 매기면 현재와 미래 소비의 상대가격이 그대로라 대체효과에 의한 초과부담이 없다":"근로소득세만 있고 이자소득세가 없으면 현재소비와 미래소비의 가격 비율이 변하지 않아 대체효과의 초과부담이 없습니다.","이자율 상승으로 해외 자본이 들어오면 원화가 절상되어(환율 하락) 경상수지가 나빠진다":"이자율이 오르면 해외 자본이 들어와 원화가 절상되어 경상수지가 나빠집니다.","이자율은 오르지 않고 통화량이 늘어 총수요 증대효과가 더 크지만 인플레이션을 부른다":"국채를 중앙은행이 인수하면 이자율 상승 없이 통화량이 늘어 총수요 효과가 크지만 인플레이션 우려가 있습니다.","이 체계에서 임금률이 낮은 사람이 높은 사람보다 큰 효용을 누리지는 않는다":"이 체계에서는 낮은 임금을 받는 사람의 효용이 높은 임금을 받는 사람보다 커질 수 없습니다.","일하는 저소득 가구에 소득과 재산 요건을 따져 장려금을 주며 우리나라는 가구 구성에 따라 혜택을 달리한다":"근로장려세제는 소득·재산 요건을 갖춘 일하는 저소득 가구에 장려금을 주며 가구 구성에 따라 혜택이 다릅니다.","자기자본의 귀속이자는 비용으로 인정하지 않고 차입 이자만 공제하므로 부채비중을 높일수록 법인세가 줄고 자금조달 방식이 왜곡된다":"법인세는 자기자본의 귀속이자를 비용으로 인정하지 않고 차입 이자만 공제하므로 부채를 늘릴수록 세금이 줄어 자금조달이 왜곡됩니다.","자본재 구입비를 빼지 않는다":"총소득형 부가가치세는 자본재 구입비를 공제하지 않고 과세하는 유형입니다.","자본재 구입비를 산 해에 전부 빼므로 과세 대상이 소비와 같아지고 투자를 촉진한다":"소비형은 자본재 구입비를 산 해에 전부 공제해 과세 대상이 소비와 같아지므로 투자를 촉진합니다.","재산권이 명확하고 거래비용이 작으면 권리를 가해자와 피해자 누구에게 주든 자발적 협상으로 같은 효율적 수준에 이른다":"코즈 정리는 재산권이 분명하고 거래비용이 작으면 권리가 누구에게 있든 협상으로 효율적 결과에 도달한다는 것입니다.","재원이 고정되면 m을 올릴 때 t도 올려야 하며 여가가 정상재면 소득효과와 대체효과가 모두 노동공급을 줄이지만 자격 심사가 필요 없어 행정이 단순하다":"재원이 고정되면 기초수당을 올릴 때 세율도 올려야 하고, 자격 심사가 없어 행정이 단순하지만 노동공급은 줄 수 있습니다.","재화끼리 수요가 독립적이면 세율은 수요의 가격탄력성에 반비례하는 역탄력성 원칙이 되어 필수재에 높은 세율이 붙는다":"재화 간 수요가 서로 영향을 주지 않으면 탄력성이 낮은 필수재에 높은 세율을 매기는 역탄력성 원칙이 됩니다.","적립방식은 민간저축이 줄어도 기금 적립이 이를 메워 국민저축이 줄지 않고 부과방식은 근로세대가 노년세대를 부양해 세대 간 재분배와 세대 간 공평성 문제가 생긴다":"적립방식은 기금 적립이 민간저축 감소를 메워 국민저축이 줄지 않고, 부과방식은 세대 간 재분배와 세대 간 공평성 문제가 생깁니다.","전략적 행동이 없다면 선호의 강도를 가장 잘 반영하는 방식은 점수투표제다":"가중치를 줘 강도를 반영할 수 있고 전략적 투표가 없다면, 점수투표제가 선호 강도를 가장 잘 나타냅니다.","전쟁 같은 사회적 격변기에 국민이 더 높은 세부담을 받아들이는 전위효과로 정부지출이 한 단계 높아져 내려오지 않는다고 했다":"전쟁 같은 격변기에는 높은 세부담을 받아들이는 전위효과로 정부지출이 한 단계 올라가 이후에도 유지된다는 이론입니다.","전제는 완전한 이동성, 지역에 대한 완전한 정보, 충분히 많은 지역사회, 지방정부 행동의 외부성 없음, 규모의 경제 없음, 재원은 재산세다":"티부 모형은 완전한 이동성, 완전한 정보, 충분히 많은 지역사회, 외부성·규모의 경제 부재, 재산세 재원이라는 전제를 둡니다.","전체의 이익에 봉사하는 것이 개인의 미덕이라는 전체주의적 사고다":"공공재 구성이 효율적이려면 편익을 내는 소비 측과 비용을 내는 생산 측 비율이 같아야 합니다.","절대귀착은 다른 조세·지출을 그대로 두고 한 조세만 보고 차별귀착은 같은 세수의 다른 조세로 바꿀 때를 보며 균형예산귀착은 그 세수로 한 지출의 분배효과까지 본다":"절대귀착은 한 조세만 보고, 차별귀착은 세수가 같은 다른 조세와 바꿀 때를 비교하며, 균형예산귀착은 지출의 분배효과까지 함께 봅니다.","점감구간에서는 소득 1원당 가처분소득 증가가 작아져 두 효과 모두 노동공급을 줄이지만 전체로는 부의 소득세나 공공부조보다 근로의욕을 더 북돋는다":"점감구간에서는 두 효과 모두 노동을 줄이지만, 전체로 보면 부의 소득세나 공공부조보다 근로의욕을 더 높입니다.","점증구간에서는 대체효과가 노동공급을 늘리고 소득효과가 줄이며 암묵적 한계세율이 0인 평탄구간에는 대체효과가 없다":"점증구간에서는 소득효과가 노동을 줄이고 대체효과가 늘리며, 평탄구간은 한계세율이 영이어서 대체효과가 없습니다.","정부가 배출 총량을 정해 나눠 주면 한계저감비용이 낮은 기업은 배출권을 팔고 높은 기업은 산다":"배출권거래제는 총량을 정해 나눈 뒤 한계저감비용이 낮은 기업은 배출권을 팔고 높은 기업은 사게 하는 제도입니다.","정부가 정보 부족이나 민간 반응을 다 통제하지 못해 정부실패가 생길 수 있다":"정부도 정보가 부족하고 민간의 반응을 통제하지 못해 오히려 비효율을 낳는 정부실패가 생길 수 있습니다.","정부의 직접 개입 없는 사적 해결 방안이며 형평성은 다루지 않아 분배 문제는 남는다":"정부 개입 없이 민간이 해결하는 방안이지만 형평성은 다루지 않아 분배 문제는 남습니다.","정부지출과 세금을 같은 금액만큼 줄이면 적자는 그대로지만 총수요는 준다":"정부지출과 세금을 같은 금액만큼 줄이면 균형재정이 유지되지만 총수요는 줄어듭니다.","정부지출의 편익은 바로 느끼지만 조세부담은 과소평가하는 재정착각과 대의민주체제의 특성으로 정부가 커진다는 리바이어던 가설을 냈다":"부캐넌은 지출 편익은 바로 느끼고 조세는 과소평가하는 재정착각과 대의제의 속성이 정부를 키운다고 보는 리바이어던 가설을 냈습니다.","정부지출이 일정하면 조세로 조달하든 국채로 조달하든 사람들이 미래 세금에 대비해 저축하므로 총수요·국민저축·이자율이 변하지 않는다는 주장이다":"조세든 국채든 정부지출이 같으면 미래 세금에 대비한 저축 때문에 총수요·국민저축·이자율이 변하지 않는다는 대등정리입니다.","정수기·방독면처럼 오염 위험을 피하려고 쓰는 돈으로 편익을 잰다":"회피행위접근법은 정수기·방독면처럼 오염 위험을 피하려고 쓰는 지출액으로 환경 개선 편익을 추정합니다.","조건부 비대응보조금도 주민의 공공재 소비와 후생을 늘린다":"조건부 비대응보조금도 공공재 소비와 주민 후생을 늘리는 효과가 있습니다.","조겐슨의 신고전파 투자이론에서 투자는 자본의 사용자비용(자본재 보유의 기회비용)이 낮을수록 늘어난다":"조겐슨의 신고전파 투자이론에서 투자는 자본재를 보유하는 기회비용인 사용자비용이 낮을수록 늘어납니다.","조세지출 남발을 막으려고 그 규모를 예산처럼 공개하는 제도다":"조세지출예산제도는 조세지출의 규모를 예산처럼 공개해 남발을 막으려는 제도입니다.","조세지출이 정당하려면 특정 행위를 촉진할 필요, 정부가 개입할 이유, 조세지출이 최선의 수단인지가 검증되어야 한다":"조세지출은 촉진 필요, 정부 개입 근거, 최선의 수단인지가 입증돼야 정당화됩니다.","주민이 교부금을 공공재 생산비(한계조세가격)가 내린 것으로 잘못 아는 재정착각과 관료의 예산극대화 동기가 원인으로 꼽힌다":"주민이 교부금을 공공재 한계조세가격 하락으로 착각하는 재정착각과 관료의 예산극대화 동기가 원인으로 설명됩니다.","중간투입물 외에 감가상각비를 추가로 빼서 과세한다":"소득형은 중간투입물에 더해 감가상각비를 공제한 나머지에 과세하는 유형입니다.","중복세대모형에서는 국가채무의 부담이 미래세대로 전가된다":"중복세대모형은 국가채무 부담이 다음 세대로 넘어간다고 설명합니다.","중앙정부 교부금에 기대면 지방의 재정자립도는 낮아진다":"교부금에 의존할수록 지방의 재정자립도는 낮아집니다.","중앙집권화율은 정부 총지출 가운데 중앙정부 직접지출의 비율로 분권 정도를 간접적으로 보여 주며 지방정부가 보조금으로 공급하는 몫은 지방 지출로 잡혀 중앙집권화 정도가 과소평가된다":"중앙집권화율은 정부 총지출 중 중앙정부 직접지출의 비율로, 보조금으로 공급되는 몫은 지방 지출로 잡혀 집권화 정도가 과소평가됩니다.","지금 임금률로 더 일하고 싶어도 못 하는 사람의 시간가치는 임금률보다 낮게 본다":"현재 임금률로 더 일하고 싶어도 못 하는 사람의 시간은 임금률보다 낮은 가치로 평가합니다.","지방세의 근간으로 삼으면 지역 사이 세원 차이로 재정불균형이 커질 수 있다":"지방세의 근간을 재산세에 의존하면 지역 간 세원 격차로 재정불균형이 커질 수 있습니다.","지방정부는 주민 선호 정보를 더 싸게 얻는다":"지방정부는 주민 선호에 대한 정보를 중앙정부보다 더 싸게 얻을 수 있습니다.","지역 간 재정능력 차이로 격차가 커질 수 있고 외부성이 있으면 공급이 비효율적이 된다":"분권에는 지역 재정능력 차이가 격차로 이어지고 외부성이 있으면 공급이 비효율적이 되는 단점이 있습니다.","지역사회가 여럿이고 주민이 원하는 지역으로 옮겨 가는 발에 의한 투표로 지방공공재가 효율적으로 배분된다고 했다":"티부 모형은 주민이 원하는 지역으로 옮겨 가는 발에 의한 투표로 지방공공재가 효율적으로 배분된다고 설명합니다.","지역 특성과 주민 욕구를 반영한 정책을 시도하기 쉽고 자치단체 사이 경쟁으로 효율적 생산을 촉진한다":"지방분권의 이점은 지역에 맞는 정책을 실험하기 쉽고 지자체 경쟁으로 효율이 높아진다는 점입니다.","지출항목별로 편성해 통제에 강하지만 비슷한 일을 하는 부서 사이의 중복을 막기 어렵다":"품목별 예산은 항목별 통제에 강하지만 비슷한 기능을 하는 부서 사이의 중복을 막지 못합니다.","진정한 선호를 밝히는 것이 우월전략이 되어 무임승차 없이 효율적 공급이 가능하다":"이 방식에서는 진실한 선호를 밝히는 것이 우월전략이어서 무임승차가 사라지고 효율적 공급이 가능합니다.","총량이 정해져 있어 감축량이 확실하고 불확실한 것은 배출권 가격이다":"감축량은 총량으로 고정되고, 시장에서 가변적인 것은 배출권의 거래 가격입니다.","총배출 30%인 300을 줄이면 q_A = 200, q_B = 100이고 배출권 가격은 200이다":"총배출의 30%를 줄이려면 한계저감비용이 같게 q_A가 200, q_B가 100이 되어 배출권 가격이 200입니다.","총비용이 4n² − 2n + 15라면 8n − 2 = 0에서 n = 1/4이고 전원합의제로 공공재를 배분하는 예로는 린달 모형이 있다":"총비용을 미분해 영으로 놓으면 가결률이 4분의 1이고, 전원합의로 공공재를 배분하는 대표 모형은 린달 모형입니다.","최적 가결률은 두 비용의 합이 가장 작은 곳이다":"최적 가결률은 의사결정비용과 외부비용을 더한 총비용이 가장 작은 지점입니다.","최종소비자가 얻어 사회후생을 늘린다":"실질적 편익은 최종소비자가 얻어 사회후생을 실제로 늘리는 편익입니다.","탄력성이 클수록 거래량이 많이 줄어 후생손실이 커지고 세율을 올려도 세수가 늘지 않을 수 있다":"탄력성이 클수록 거래량 감소가 커서 후생손실이 늘고 세율을 높여도 세수가 안 늘 수 있습니다.","탈세를 기대효용 극대화 문제로 보고 납세자의 절대위험기피도가 체감한다고 가정한다":"납세자가 탈세로 얻는 기대효용을 극대화한다고 보며, 절대위험기피도 체감을 가정해 분석하는 모형입니다.","통행료·사용료·수수료, 주행거리에 비례한 자동차세가 예다":"통행료·사용료·수수료와 주행거리에 비례하는 자동차세가 편익원칙의 예입니다.","투표의 역설이 있으면 존재하지 않고 강선호라면 있더라도 하나뿐이다":"투표의 역설이 있으면 꽁도세 승자가 존재하지 않고, 강선호라면 있어도 하나뿐입니다.","특정 재화 구입비를 공제하면 그 재화의 상대가격이 낮아지며 우리나라 교육비는 세액공제 대상이다":"특정 재화 구입비를 공제하면 그 재화의 상대가격이 낮아지는 효과가 있고, 교육비가 세액공제 대상입니다.","편익이 미치는 공간적 범위가 전국이거나 외부성이 지역 경계를 넘거나 규모의 경제가 크거나 무임승차 가능성이 높은 공공재는 중앙정부가 공급한다":"효과가 전국에 미치거나 지역 경계를 넘거나 규모의 경제가 큰 공공재는 중앙정부가 맡는 쪽이 적합합니다.","평균비용이 계속 줄어드는 구간에서는 한계비용이 평균비용보다 작아 한 기업이 생산하는 편이 싸다":"평균비용이 계속 내려가는 구간에서는 한계비용이 평균비용보다 낮아 한 기업이 생산해야 비용이 가장 적습니다.","평균세율이 소득과 함께 오르면 누진세이고 세수탄력성(한계세율/평균세율)이 1보다 크다":"평균세율이 소득과 함께 오르면 누진세이고, 세수탄력성이 1보다 크다는 것으로도 확인합니다.","하위 40% 점유율을 상위 20% 점유율로 나눈 값이라 완전 균등이면 2이고 클수록 평등하다":"하위 40% 점유율을 상위 20% 점유율로 나누어 구하며 완전 균등이면 2가 되고 값이 클수록 평등함을 뜻합니다.","하위 몇 %가 전체 소득의 몇 %를 갖는지 이은 곡선으로 대각선에 가까울수록 평등하고 서수적 평가라서 곡선이 교차하면 비교할 수 없다":"로렌츠곡선은 소득 하위 계층의 누적 점유율을 이은 곡선으로 대각선에 가까울수록 평등하며, 서수적 평가라 곡선이 교차하면 비교할 수 없습니다.","한계비용 50이 일정하고 보상수요가 P = 100 − Q일 때 단위당 20을 과세하면 Q가 50에서 30으로 줄어 세수 600, 사중손실 200이고 비효율성계수는 1/3이다":"한계비용이 일정할 때 단위당 20을 과세하면 거래량이 50에서 30으로 줄어 세수 600, 사중손실 200이며 비효율성계수는 3분의 1입니다.","한계세율과 관계없이 같은 금액을 깎아 주므로 감면 총액이 같다면 소득공제를 세액공제로 바꿀 때 수직적 공평이 나아진다":"세액공제는 한계세율과 관계없이 같은 금액을 깎아 주므로 소득공제를 이로 바꾸면 수직적 공평이 나아집니다.","한계세율과 평균세율이 같으면 비례세다":"한계세율과 평균세율이 같다면 소득에 상관없이 세율이 일정한 비례세입니다.","한계세율은 마지막 구간의 18%이고 실효세율은 총소득 5,500만원으로 나눈 약 7.85%다":"마지막 구간의 18%가 한계세율이고, 총세액을 총소득으로 나눈 약 7.85%가 실효세율입니다.","한계소비성향이 c이면 정부지출승수는 1/(1 − c), 감세승수는 c/(1 − c)라 같은 금액이면 정부지출 증가의 총수요 효과가 크다":"정부지출승수와 감세승수는 한계소비성향으로 정해지므로 같은 금액이면 지출 증가가 총수요를 더 크게 늘립니다.","한계실효세율은 (세전 수익률 − 세후 수익률)/세전 수익률로 음수면 조세가 투자를 촉진하고 사용자비용탄력성이 작을수록 조세정책 효과도 작다":"한계실효세율은 세전 수익률에서 세후 수익률을 뺀 값을 세전 수익률로 나눈 것으로 음수이면 조세가 투자를 촉진합니다.","한 사람의 사용이 다른 사용자에게 외부성을 주기 때문이며 연근해 어족 자원 고갈이 대표적이다":"사용자가 서로 외부성을 주고받는 구조라 어족 자원을 둘러싼 연근해 어업이 비극의 대표 사례입니다.","한 사람의 행동이 대가 없이 제3자에게 이득이나 손해를 주는 현상으로 생산과 소비 모두에서 생긴다":"외부성은 거래 당사자가 아닌 사람에게 대가 없이 이득이나 손해를 미치며, 생산에서도 소비에서도 나타납니다.","한 사람이 더 소비해도 남의 소비가 줄지 않는 성질로 소비자 추가의 한계비용이 0이다":"비경합성은 한 사람이 더 소비해도 남의 소비가 줄지 않는 성질이어서 소비자가 하나 늘 때의 한계비용이 영입니다.","한 지역의 공급이 다른 지역에 외부성을 주면 분권적 공급이 비효율적일 수 있다":"지역 간 외부성이 있을 때는 지방정부가 각자 공급하면 비효율이 생길 수 있습니다.","할인율 10%에서 지금 −3,000, 1년 뒤 1,100, 2년 뒤 2,420이면 NPV = −3,000 + 1,000 + 2,000 = 0이다":"할인율로 현금흐름을 현재가치로 바꿔 합하면 −3,000과 1,000, 2,000이 상쇄돼 순현재가치가 0입니다.","할인율 7%에서 NPV는 A 56.9, B 74.8로 B가 낫다":"할인율 7%로 계산한 순현재가치는 A가 56.9, B가 74.8로 B가 더 높습니다.","할인율이 높을수록 먼 미래 편익이 크게 깎여 편익이 초기에 몰린 단기 사업이 유리하다":"할인율이 크면 미래 편익의 현재가치가 줄어, 빨리 편익이 나오는 단기 사업이 상대적으로 낫습니다.","할인율이 약 5.2%보다 낮으면 A의 NPV가 더 커져 순위가 바뀐다":"할인율이 약 5.2%보다 낮아지면 A의 순현재가치가 더 커져서 두 사업의 순위가 뒤바뀝니다.","합 15 − 0.15Z = 3에서 Z = 80이고 P_B = 2이므로 B의 부담비율은 2/3다":"합산 역수요를 3과 같게 놓아 공급량 80을 얻고, 그때 B의 가격이 2이므로 B의 부담비율이 3분의 2입니다.","해안 6명이 P = 200 − 2Q, 내륙 4명이 P = 150 − 3Q이고 MC = 840이면 1,800 − 24Q = 840에서 Q = 40이고 1인 부담은 120과 30이다":"집단별 수요를 합친 식을 한계비용과 같게 놓으면 공급량이 40이고 1인당 부담은 120과 30입니다.","행동과 관계없이 걷으므로 초과부담이 없고 현금보조는 음(−)의 정액세라 초과부담이 없다":"정액세는 행동과 무관하게 걷어서 초과부담이 없고, 현금보조는 음의 정액세여서 초과부담이 없습니다.","헤도닉가격법은 주택가격 같은 시장자료, 여행비용법은 방문 비용으로 환경가치를 추정한다":"주택가격 같은 시장자료를 이용하는 것이 헤도닉가격법이고 방문에 든 비용으로 추정하는 것이 여행비용법입니다.","현재소비는 대체효과로 늘고 소득효과로 줄어 방향이 불분명하며 미래소비는 두 효과 모두 줄이고 저축의 증감도 알 수 없다":"현재소비는 효과가 엇갈려 방향이 불분명하고 미래소비는 두 효과 모두 줄이며 저축의 증감은 알 수 없습니다.","효용을 측정·비교할 수 있다고 보고 그 사회의 가치판단에 따라 모양이 정해진다":"사회후생함수는 개인 효용을 비교·측정할 수 있다고 전제하고, 사회의 가치판단에 따라 그 모양이 정해집니다.","효용이 낮은 사람에게 큰 가중치를 주며 이 성향이 극단으로 가면 롤즈의 W = min(U_A, U_B)가 되어 사회무차별곡선이 L자다":"평등주의는 효용이 낮은 사람에게 가중치를 더 주며, 극단에 이르면 가장 못한 사람의 효용만 보는 롤즈 함수와 L자 무차별곡선이 됩니다.","효용 총합이 가장 큰 분배를 바람직하다고 보아 불균등한 분배도 정당화할 수 있다":"벤담의 공리주의는 효용 총합이 가장 큰 분배를 옳다고 보기 때문에 불균등한 분배도 정당화할 수 있습니다.","효용함수가 같고 소득의 한계효용이 체감하며 총소득이 고정되면 완전 균등분배가 최적이라고 했다":"에지워스는 동일한 효용함수와 체감하는 한계효용, 일정한 총소득을 전제로 균등분배가 최적이라 주장했습니다.","효율과 공평을 함께 보며 한계세율은 0과 1 사이이고 최고 소득 구간의 한계세율은 0이다":"멀리스의 비선형 최적소득세는 효율과 공평을 함께 보며 한계세율이 영과 1 사이이고 최고 소득 구간에서는 영입니다.","효율성만 본 원칙이라 필수재에 낮은 세율을 매기는 것은 램지 규칙에는 어긋나도 공평 면에서는 바람직할 수 있다":"필수재에 낮은 세율을 주는 것은 효율 면에선 램지 규칙에 어긋나지만 분배 면에서는 정당화될 여지가 있습니다.","효율적 생산량을 내지만 P < AC라 손실이 나서 일반 세원으로 메워야 한다":"한계비용 가격은 효율적 생산량을 이루나 가격이 평균비용에 못 미쳐 생기는 손실을 일반 세원으로 메워야 합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
